window.QUIZ_BANK = {"version": "2d9619023cdddbd0", "questions": [{"id": "src-19f7f928932c-q001", "chapter": 3, "text": "Trong phương pháp sản xuất giá trị thặng dư tuyệt đối, giới hạn tối thiểu của ngày lao động là gì?", "options": [{"label": "A", "text": "Đủ bù đắp giá trị SLĐ của công nhân"}, {"label": "B", "text": "Lớn hơn thời gian lao động tất yếu"}, {"label": "C", "text": "Do nhà tư bản quy định"}, {"label": "D", "text": "Tất cả các đáp án trên"}], "answer": "B", "explanation": "B; trùng nội dung câu trung bình 6 của Chuong3_Hanh.docx (đáp án C theo thứ tự khác)."}, {"id": "src-19f7f928932c-q002", "chapter": 3, "text": "Phương pháp sản xuất giá trị thặng dư tương đối thực hiện bằng cách nào?", "options": [{"label": "A", "text": "Thời gian lao động tất yếu và giá trị SLĐ thay đổi"}, {"label": "B", "text": "Hạ thấp giá trị SLĐ"}, {"label": "C", "text": "Rút ngắn thời gian lao động tất yếu trong điều kiện ngày lao động không đổi"}, {"label": "D", "text": "Tất cả các đáp án trên"}], "answer": "D", "explanation": "D theo cách hiểu A, B là các biến đổi cùng chiều với C: giá trị sức lao động và thời gian tất yếu đều giảm. C là cách diễn đạt chính xác nhất; A nên viết rõ “giảm”."}, {"id": "src-19f7f928932c-q004", "chapter": 3, "text": "Điểm giống nhau giữa giá trị thặng dư tương đối và giá trị thặng dư siêu ngạch là gì?", "options": [{"label": "A", "text": "Tăng năng suất lao động ngành nông nghiệp"}, {"label": "B", "text": "Tăng năng suất lao động cá biệt"}, {"label": "C", "text": "Tăng năng suất lao động xã hội"}, {"label": "D", "text": "Tăng năng suất lao động"}], "answer": "D", "explanation": "D là điểm chung, không buộc cùng mức cá biệt hay xã hội."}, {"id": "src-19f7f928932c-q005", "chapter": 3, "text": "Sự khác nhau giữa giá trị thặng dư siêu ngạch và giá trị thặng dư tương đối thể hiện ở nội dung nào?", "options": [{"label": "A", "text": "Dựa vào tăng số lượng lao động"}, {"label": "B", "text": "Dựa trên cơ sở tăng năng suất lao động cá biệt"}, {"label": "C", "text": "Dựa trên cơ sở tăng cường độ lao động"}, {"label": "D", "text": "Tất cả các đáp án trên"}], "answer": "B", "explanation": "B xét đặc trưng của siêu ngạch."}, {"id": "src-19f7f928932c-q006", "chapter": 3, "text": "Giá trị thặng dư là gì?", "options": [{"label": "A", "text": "Lợi nhuận thu được của người sản xuất, kinh doanh"}, {"label": "B", "text": "Giá trị tư bản tăng lên"}, {"label": "C", "text": "Phần giá trị dôi ra ngoài giá trị SLĐ do công nhân làm ra"}, {"label": "D", "text": "Phần chênh lệch giữa giá trị hàng hóa với chi phí sản xuất TBCN"}], "answer": "C", "explanation": "C định nghĩa chính xác; D là biểu hiện lợi nhuận, cần thêm giả định bán đúng giá trị mới đồng nhất về lượng."}, {"id": "src-19f7f928932c-q008", "chapter": 3, "text": "Căn cứ nào để phân chia Tư bản bất biến và Tư bản khả biến?", "options": [{"label": "A", "text": "Tốc độ chu chuyển của tư bản"}, {"label": "B", "text": "Vai trò của các bộ phận tư bản trong quá trình sản xuất giá trị thặng dư"}, {"label": "C", "text": "Hao mòn hữu hình hoặc vô hình"}, {"label": "D", "text": "Phương thức chuyển giá trị các bộ phận tư bản sang sản phẩm"}], "answer": "B", "explanation": "B."}, {"id": "src-19f7f928932c-q009", "chapter": 3, "text": "Căn cứ nào để phân chia tư bản cố định và tư bản lưu động?", "options": [{"label": "A", "text": "Tốc độ chu chuyển của tư bản"}, {"label": "B", "text": "Phương thức chuyển giá trị các bộ phận tư bản sang sản phẩm"}, {"label": "C", "text": "Vai trò của các bộ phận tư bản trong quá trình sản xuất giá trị thặng dư"}, {"label": "D", "text": "Sự thay đổi về lượng trong quá trình sản xuất"}], "answer": "B", "explanation": "B; đối chiếu Chuong3_Hien.docx câu 50."}, {"id": "src-19f7f928932c-q010", "chapter": 3, "text": "Tư bản ứng trước bao gồm những đại lượng nào?", "options": [{"label": "A", "text": "Tư bản bất biến và Tư bản khả biến"}, {"label": "B", "text": "Tư bản bất biến, Tư bản khả biến và bộ phận tư bản tăng thêm trong quá tình sản xuất"}, {"label": "C", "text": "Bộ phận c1 và c2"}, {"label": "D", "text": "Tất cả các đáp án trên"}], "answer": "A", "explanation": "A: K=c+v."}, {"id": "src-19f7f928932c-q011", "chapter": 3, "text": "Tư bản là gì?", "options": [{"label": "A", "text": "Tiền và máy móc thiết bị"}, {"label": "B", "text": "Tiền có khả năng sinh lời"}, {"label": "C", "text": "Công cụ sản xuất và nguyên vật liệu"}, {"label": "D", "text": "Giá trị mang lại giá trị thặng dư bằng cách bóc lột lao động làm thuê"}], "answer": "D", "explanation": "D."}, {"id": "src-19f7f928932c-q013", "chapter": 3, "text": "Hàng hóa SLĐ là gì?", "options": [{"label": "A", "text": "Tồn tại trong mọi nền sản xuất của xã hội"}, {"label": "B", "text": "Là loại hàng hóa đặc biệt có giá trị sử dụng có khả năng tạo ra giá trị mới trong quá trình sử dụng"}, {"label": "C", "text": "Chỉ có giá trị nhất định"}, {"label": "D", "text": "Tất cả các đáp án trên"}], "answer": "B", "explanation": "B; nên bổ sung “lớn hơn giá trị bản thân nó” để nêu đặc tính đầy đủ."}, {"id": "src-19f7f928932c-q014", "chapter": 3, "text": "TBBB và TBKB thuộc phạm trù tư bản nào?", "options": [{"label": "A", "text": "Sản xuất"}, {"label": "B", "text": "Tiền tệ"}, {"label": "C", "text": "Hàng hóa"}, {"label": "D", "text": "Lưu thông"}], "answer": "A", "explanation": "A; đối chiếu Chuong3_Hanh.docx câu 19."}, {"id": "src-19f7f928932c-q015", "chapter": 3, "text": "Tỷ suất giá trị thặng dư phản ánh điều gì?", "options": [{"label": "A", "text": "Hiệu quả của tư bản"}, {"label": "B", "text": "Quy mô bóc lột của tư bản"}, {"label": "C", "text": "Trình độ bóc lột của tư bản đối với công nhân làm thuê"}, {"label": "D", "text": "Tất cả các đáp án trên"}], "answer": "C", "explanation": "C; đối chiếu Chuong3_Hanh.docx câu 15."}, {"id": "src-19f7f928932c-q016", "chapter": 3, "text": "Để tăng khối lượng giá trị thặng dư có thể sử dụng cách thức nào?", "options": [{"label": "A", "text": "Tăng cường độ lao động khi ngày lao động không đổi"}, {"label": "B", "text": "Kéo dài thời gian lao động trong ngày"}, {"label": "C", "text": "Tăng năng suất lao động"}, {"label": "D", "text": "Tất cả các đáp án trên"}], "answer": "D", "explanation": "D trong các điều kiện phù hợp; “tăng năng suất” ở C phải hiểu theo cơ chế tạo thặng dư tương đối/siêu ngạch, không phải mọi tăng năng suất đều tự động tăng tổng giá trị."}, {"id": "src-19f7f928932c-q017", "chapter": 3, "text": "Khối lượng giá trị thặng dư phản ánh điều gì?", "options": [{"label": "A", "text": "Chỉ cho nhà tư bản biết nơi đầu tư có lợi"}, {"label": "B", "text": "Trình độ bóc lột giá trị thặng dự của nhà tư bản"}, {"label": "C", "text": "Quy mô bóc lột giá trị thặng dự của nhà tư bản"}, {"label": "D", "text": "Lượng lợi nhuận mà các nhà tư bản nhận được khi cạnh tranh tự do"}], "answer": "C", "explanation": "C."}, {"id": "src-19f7f928932c-q018", "chapter": 3, "text": "Phương pháp sản xuất giá trị thặng dư tuyệt đối thực hiện bằng cách nào?", "options": [{"label": "A", "text": "Tiết kiệm chi phí sản xuất"}, {"label": "B", "text": "Sử dụng kỹ thuật tiên tiến, cải tiến tổ chức quản lý"}, {"label": "C", "text": "Kéo dài thời gian của ngày lao động, còn thời gian lao động tất yếu không đổi"}, {"label": "D", "text": "Tất cả các đáp án trên"}], "answer": "C", "explanation": "C."}, {"id": "src-19f7f928932c-q019", "chapter": 3, "text": "Giá trị hàng hóa SLĐ gồm những giá trị nào?", "options": [{"label": "A", "text": "Chi phí đào tạo người lao động"}, {"label": "B", "text": "Giá trị các hàng hóa do người lao động tạo ra"}, {"label": "C", "text": "Chi phí sản xuất tư bản chủ nghĩa"}, {"label": "D", "text": "Cả ý a và c"}], "answer": "A", "explanation": "A là một bộ phận; đề chưa liệt kê đầy đủ các bộ phận còn lại."}, {"id": "src-19f7f928932c-q020", "chapter": 3, "text": "Thực chất của quá trình tích lũy tư bản là gì?", "options": [{"label": "A", "text": "Tăng cấu tạo hữu cơ của tư bản"}, {"label": "B", "text": "Tăng quy mô của tư bản cá biệt bằng cách biến giá trị thặng dư thành tư bản"}, {"label": "C", "text": "Tăng năng suất lao động cá biệt"}, {"label": "D", "text": "Tăng năng suất lao động xã hội"}], "answer": "B", "explanation": "B."}, {"id": "src-19f7f928932c-q021", "chapter": 3, "text": "Phạm trù tỷ suất lợi nhuận cho biết điều gì?", "options": [{"label": "A", "text": "Trình độ kinh doanh của doanh nghiệp"}, {"label": "B", "text": "Mức độ hiệu quả của việc sử dụng lao động"}, {"label": "C", "text": "Khả năng bóc lột giá trị thặng dư của doanh nghiệp"}, {"label": "D", "text": "Khả năng sinh lời (mức doanh lợi) của việc đầu tư"}], "answer": "D", "explanation": "D."}, {"id": "src-19f7f928932c-q022", "chapter": 3, "text": "Lợi nhuận bình quân hình thành trong điều kiện nào?", "options": [{"label": "A", "text": "Sản xuất hàng hóa"}, {"label": "B", "text": "Kinh tế thị trường"}, {"label": "C", "text": "Cạnh tranh tự do"}, {"label": "D", "text": "Phân công lao động"}], "answer": "C", "explanation": "C."}, {"id": "src-19f7f928932c-q023", "chapter": 3, "text": "Bản chất của lợi nhuận thương nghiệp là gì?", "options": [{"label": "A", "text": "Lợi nhuận do kinh doanh hàng hóa mang lại"}, {"label": "B", "text": "Một phần của lợi nhuận bình quân do tư bản công nghiệp nhường cho tư bản thương nghiêp"}, {"label": "C", "text": "Lợi nhuận của tư bản hàng hóa"}, {"label": "D", "text": "Giá bán lẻ cao hơn giá bán buôn"}], "answer": "B", "explanation": "B gần nhất; diễn đạt chuẩn là một phần giá trị thặng dư được nhường cho tư bản thương nghiệp."}, {"id": "src-19f7f928932c-q024", "chapter": 3, "text": "Tỷ suất lợi nhuận bình quân hình thành do nguyên nhân nào?", "options": [{"label": "A", "text": "Tư bản có thể tự do di chuyển giữa các ngành"}, {"label": "B", "text": "Phân công lao động xã hội"}, {"label": "C", "text": "Hình thành độc quyền trong kinh tế"}, {"label": "D", "text": "Các nhà tư bản quy định"}], "answer": "A", "explanation": "A."}, {"id": "src-19f7f928932c-q025", "chapter": 3, "text": "Chi phí tư bản chủ nghĩa là gì?", "options": [{"label": "A", "text": "Chi phí lao động thực tế của xã hội để sản xuất ra hàng hóa"}, {"label": "B", "text": "Chi phí cho hoạt động kinh doanh hàng hóa"}, {"label": "C", "text": "Chi phí thuần túy về tư bản"}, {"label": "D", "text": "Chi phí chuyển nhượng thương hiệu"}], "answer": "C", "explanation": "C; k=c+v, không bao gồm lao động thặng dư."}, {"id": "src-19f7f928932c-q026", "chapter": 3, "text": "Quan hệ về lượng giữa lợi nhuận và giá trị thặng dư thể hiện ở nội dung nào?", "options": [{"label": "A", "text": "Lợi nhuận lớn hơn giá trị thặng dư"}, {"label": "B", "text": "Lợi nhuận nhỏ hơn giá trị thặng dư"}, {"label": "C", "text": "Lợi nhuận bằng giá trị thặng dư"}, {"label": "D", "text": "Lợi nhuận và giá trị thặng dư không đồng nhất về lượng nhưng tổng của lợi nhuận thì bằng tổng của giá trị thặng dư"}], "answer": "D", "explanation": "D trong phạm vi toàn xã hội theo mô hình lý luận."}, {"id": "src-19f7f928932c-q027", "chapter": 3, "text": "Tỷ suất lợi nhuận không phụ thuộc vào nhân tố nào?", "options": [{"label": "A", "text": "Tỷ suất giá trị thặng dư"}, {"label": "B", "text": "Tốc độ chu chuyển của tư bản"}, {"label": "C", "text": "Đại lượng tư bản ứng trước"}, {"label": "D", "text": "Hoạt động kinh doanh hàng hóa"}], "answer": "D", "explanation": "D là phương án phù hợp nhất với danh sách nhân tố trực tiếp trong giáo trình. Hiểu rộng, hoạt động kinh doanh vẫn có thể ảnh hưởng lợi nhuận nên cách hỏi cần thu hẹp."}, {"id": "src-19f7f928932c-q028", "chapter": 3, "text": "Một tư bản cá biệt ứng trước 400.000 đơn vị tiền tệ (đvtt) để sản xuất hàng hóa với c/v = 4/1; m’ = 250%. Giá trị hàng hóa được tạo ra là bao nhiêu?", "options": [{"label": "A", "text": "320.000 đvtt"}, {"label": "B", "text": "280.000 đvtt"}, {"label": "C", "text": "200.000 đvtt"}, {"label": "D", "text": "600.000 đvtt"}], "answer": "D", "explanation": "v=400.000/5=80.000; m=2,5v=200.000; W=400.000+200.000=600.000 → D. Giả định toàn bộ c chuyển vào sản phẩm và một chu kỳ như mô hình bài tập."}, {"id": "src-19f7f928932c-q029", "chapter": 3, "text": "Muốn tăng tỷ suất lợi nhuận thì chủ tư bản cần làm gì?", "options": [{"label": "A", "text": "Học tập để kinh doanh giỏi hơn"}, {"label": "B", "text": "Tăng tốc độ chu chuyển của tư bản"}, {"label": "C", "text": "Tăng quy mô tích lũy"}, {"label": "D", "text": "Tăng chi phí cho quảng cáo"}], "answer": "B", "explanation": "B."}, {"id": "src-19f7f928932c-q030", "chapter": 3, "text": "Một doanh nghiệp tư bản năm thứ nhất ứng ra 500.000 £ để sản xuất hàng hóa, c/v = 4/1, m’ = 200%, cuối năm doanh nghiệp dành 50% khối lượng giá trị thặng dư đưa vào tích lũy. Lượng tư bản được tích lũy cuối năm thứ nhất của doanh nghiệp này là bao nhiêu?", "options": [{"label": "A", "text": "150.000£"}, {"label": "B", "text": "100.000£"}, {"label": "C", "text": "200.000£"}, {"label": "D", "text": "250.000£"}], "answer": "B", "explanation": "v=500.000/5=100.000; m=2v=200.000; tích lũy=50%×200.000=100.000 £ → B."}, {"id": "src-19f7f928932c-q031", "chapter": 3, "text": "Hệ quả của tích lũy tư bản là gì?", "options": [{"label": "A", "text": "Chủ tư bản ít giá trị thặng dư hơn vì đã biến chúng thành tư bản"}, {"label": "B", "text": "Tăng quy mô của tư bản"}, {"label": "C", "text": "Tăng tốc độ chu chuyển của tư bản"}, {"label": "D", "text": "Tăng thời gian lưu thông"}], "answer": "B", "explanation": "B."}, {"id": "src-19f7f928932c-q032", "chapter": 3, "text": "Lợi nhuận bình quân là gì?", "options": [{"label": "A", "text": "Chênh lệch giữa chi phí sản xuất tư bản chủ nghĩa và giá trị hàng hóa"}, {"label": "B", "text": "Chênh lệch giữa tư bản sử dụng và tư bản đã tiêu dùng"}, {"label": "C", "text": "Lượng lợi nhuận bằng nhau của những tư bản như nhau đầu tư vào các ngành sản xuất khác nhau"}, {"label": "D", "text": "Lượng lợi nhuận mà tư bản công nghiệp nhường cho tư bản thương nghiệp"}], "answer": "C", "explanation": "C; đối chiếu Chuong3_Hien.docx câu 71."}, {"id": "src-19f7f928932c-q033", "chapter": 3, "text": "Giả sử một doanh nghiệp có lượng tư bản ứng trước đầu năm là 780.000 đvtt, trong đó giá trị tư bản bất biến gấp 5 lần tư bản khả biến; tỷ suất giá trị thặng dư là 300%. Tỷ suất lợi nhuận mà doanh nghiệp này đạt được là bao nhiêu?", "options": [{"label": "A", "text": "40%"}, {"label": "B", "text": "45%"}, {"label": "C", "text": "50%"}, {"label": "D", "text": "60%"}], "answer": "C", "explanation": "v=780.000/6=130.000; m=390.000; p′=390.000/780.000×100%=50% → C."}, {"id": "src-19f7f928932c-q035", "chapter": 3, "text": "Tư bản cố định và tư bản lưu động là bộ phận của tư bản nào?", "options": [{"label": "A", "text": "Tư bản tiền tệ"}, {"label": "B", "text": "Tư bản sản xuất"}, {"label": "C", "text": "Tư bản hàng hóa"}, {"label": "D", "text": "Tư bản cho vay"}], "answer": "B", "explanation": "B."}, {"id": "src-19f7f928932c-q036", "chapter": 3, "text": "Một doanh nghiệp tư bản cá biệt ứng ra 900.000 đvtt để sản xuất hàng hóa với c/v = 8/1, m’ = 200%. Tỷ suất lợi nhuận mà doanh nghiệp này đạt được là bao nhiêu?", "options": [{"label": "A", "text": "18,3%"}, {"label": "B", "text": "20,5%"}, {"label": "C", "text": "22,2%"}, {"label": "D", "text": "25,2%"}], "answer": "C", "explanation": "v=900.000/9=100.000; m=200.000; p′=200.000/900.000×100%≈22,2% → C."}, {"id": "src-19f7f928932c-q037", "chapter": 3, "text": "Tư bản lưu động bao gồm những giá trị nào?", "options": [{"label": "A", "text": "Máy móc, thiết bị, nhà xưởng"}, {"label": "B", "text": "Nguyên, nhiên vật liệu và sức lao động"}, {"label": "C", "text": "Chi phí cố định cho sản xuất"}, {"label": "D", "text": "Chi phí cho thuê mướn mặt bằng kinh doanh"}], "answer": "B", "explanation": "B."}, {"id": "src-19f7f928932c-q038", "chapter": 3, "text": "Quy luật chung của tích lũy tư bản bao gồm nội dung nào?", "options": [{"label": "A", "text": "Tăng số lượng các nhà tư bản"}, {"label": "B", "text": "Tăng cường độ lao động"}, {"label": "C", "text": "Tăng chênh lệch thu nhập giữa nhà tư bản và công nhân làm thuê"}, {"label": "D", "text": "Tăng tỷ suất lợi nhuận"}], "answer": "C", "explanation": "C."}, {"id": "src-19f7f928932c-q039", "chapter": 3, "text": "Giả sử trong điều kiện cạnh tranh tự do, nền sản xuất xã hội gồm 3 ngành với cơ cấu tư bản đầu tư lần lượt là 2600C + 400V; 3500C + 500V; 2400C + 600V; m’ đều là 200%. Tỷ suất lợi nhuận bình quân được xác định là bao nhiêu?", "options": [{"label": "A", "text": "20%"}, {"label": "B", "text": "25%"}, {"label": "C", "text": "30%"}, {"label": "D", "text": "35%"}], "answer": "C", "explanation": "Tổng K=3.000+4.000+3.000=10.000; tổng m=2×(400+500+600)=3.000; p̄′=30% → C."}, {"id": "src-811c9106b75b-q001", "chapter": 2, "text": "Theo góc độ nghiên cứu kinh tế chính trị, hàng hóa là gì?", "options": [{"label": "A", "text": "Sản phẩm của thị trường"}, {"label": "B", "text": "Sản phẩm của quá trình sản xuất"}, {"label": "C", "text": "Sản phẩm để thỏa mãn nhu cầu của con người"}, {"label": "D", "text": "Sản phẩm của lao động, có thể thỏa mãn nhu cầu nào đó của con người thông qua trao đổi, mua bán"}], "answer": "D", "explanation": "D bao gồm điều kiện trao đổi."}, {"id": "src-811c9106b75b-q002", "chapter": 2, "text": "Sản xuất hàng hóa tồn tại trong điều kiện nào?", "options": [{"label": "A", "text": "Mọi chế độ xã hội"}, {"label": "B", "text": "Trong các chế độ có tư hữu và có có tính chất tư nhân của sản xuất"}, {"label": "C", "text": "Trong xã hội có PCLĐ xã hội"}, {"label": "D", "text": "Trong xã hội có PCLĐ xã hội và có tính chất tư nhân của sản xuất"}], "answer": "D", "explanation": "D gần nhất; nên thay “tính chất tư nhân” bằng “sự tách biệt tương đối về kinh tế”."}, {"id": "src-811c9106b75b-q003", "chapter": 2, "text": "Giá cả của hàng hóa là gì?", "options": [{"label": "A", "text": "Giá trị của hàng hóa"}, {"label": "B", "text": "Quan hệ về lượng giữa hàng hóa và tiền"}, {"label": "C", "text": "Tổng của chi phí sản xuất và lợi nhuận"}, {"label": "D", "text": "Biểu hiện bằng tiền của giá trị hàng hóa"}], "answer": "D", "explanation": "D."}, {"id": "src-811c9106b75b-q006", "chapter": 2, "text": "Giá trị sử dụng của hàng hóa được tạo thành do lao động nào dưới đây ?", "options": [{"label": "A", "text": "Lao động trừu tượng"}, {"label": "B", "text": "Lao động giản đơn"}, {"label": "C", "text": "Lao động cụ thể"}, {"label": "D", "text": "Lao động phức tạp"}], "answer": "C", "explanation": "C."}, {"id": "src-811c9106b75b-q007", "chapter": 2, "text": "Giá trị hàng hóa được hình thành do lao động nào dưới đây?", "options": [{"label": "A", "text": "Lao động trừu tượng"}, {"label": "B", "text": "Lao động giản đơn"}, {"label": "C", "text": "Lao động cụ thể"}, {"label": "D", "text": "Lao động phức tạp"}], "answer": "A", "explanation": "A."}, {"id": "src-811c9106b75b-q008", "chapter": 2, "text": "Số lượng giá trị sử dụng của 1 hàng hóa có đặc điểm gì?", "options": [{"label": "A", "text": "Mỗi hàng hóa có duy nhất 1 giá trị sử dụng"}, {"label": "B", "text": "Mỗi hàng hóa có thể có nhiều hơn 1 giá trị sử dụng"}, {"label": "C", "text": "Hàng hóa có thể không có giá trị sử dụng"}, {"label": "D", "text": "Cả ý b và ý c đều đúng"}], "answer": "B", "explanation": "B."}, {"id": "src-811c9106b75b-q009", "chapter": 2, "text": "Thị trường có vai trò như thế nào ?", "options": [{"label": "A", "text": "Thị trường là nơi sản xuất và cung ứng các hàng hóa, dịch vụ công cộng"}, {"label": "B", "text": "Thị trường đòi hỏi các chủ thể sản xuất cung cấp thông tin đầy đủ về sản phẩm của mình"}, {"label": "C", "text": "Thị trường là điều kiện, môi trường cho sản xuất phát triển"}, {"label": "D", "text": "Tất cả các đáp án trên"}], "answer": "C", "explanation": "C; A gán hoạt động sản xuất cho thị trường."}, {"id": "src-811c9106b75b-q010", "chapter": 2, "text": "Điều kiện ra đời và tồn tại của sản xuất hàng hóa không bao gồm nội dung nào?", "options": [{"label": "A", "text": "Phân công lao động xã hội"}, {"label": "B", "text": "Sự tách biệt tương đối về kinh tế của những người sản xuất"}, {"label": "C", "text": "Yếu tố thị trường để tiêu thụ hàng hóa"}, {"label": "D", "text": "Tất cả các ý trên"}], "answer": "C", "explanation": "C là yếu tố không thuộc hai điều kiện ra đời."}, {"id": "src-811c9106b75b-q011", "chapter": 2, "text": "Lao động cụ thể là gì?", "options": [{"label": "A", "text": "Lao động mà ai cũng có thể làm được"}, {"label": "B", "text": "Lao động tạo ra giá trị của hàng hóa"}, {"label": "C", "text": "Lao động mà tập hợp của chúng tạo thành hệ thống PCLĐ xã hội"}, {"label": "D", "text": "Tất cả các ý trên"}], "answer": "C", "explanation": "C phù hợp nhất trong bốn lựa chọn."}, {"id": "src-811c9106b75b-q013", "chapter": 2, "text": "Lượng giá trị của 1 đơn vị hàng hóa thay đổi như thế nào ?", "options": [{"label": "A", "text": "Tăng khi năng suất lao động tăng"}, {"label": "B", "text": "Tăng khi năng suất lao động giảm"}, {"label": "C", "text": "Tăng khi trình độ lành nghề của người lao động tăng"}, {"label": "D", "text": "Tăng khi hiệu quả sử dụng tư liệu sản xuất tăng"}], "answer": "B", "explanation": "B."}, {"id": "src-811c9106b75b-q015", "chapter": 2, "text": "Lao động giản đơn là loại lao động có đặc điểm gì ?", "options": [{"label": "A", "text": "Bất kỳ người lao động nào cũng có thể thực hiện"}, {"label": "B", "text": "Chỉ những người lao động đã qua đào tạo mới có thể thực hiện"}, {"label": "C", "text": "Chỉ những người lao động lành nghề mới có thể thực hiện được"}, {"label": "D", "text": "Trong một nghề nghiệp, chuyên môn nhất định"}], "answer": "A", "explanation": "A, hiểu là người bình thường có khả năng lao động."}, {"id": "src-811c9106b75b-q016", "chapter": 2, "text": "Lao động phức tạp là loại lao động như thế nào ?", "options": [{"label": "A", "text": "Bất kỳ người lao động nào cũng có thể thực hiện"}, {"label": "B", "text": "Chỉ những người lao động đã qua đào tạo mới có thể thực hiện"}, {"label": "C", "text": "Có mục đích, đối tượng và phương thức và kết quả riêng"}, {"label": "D", "text": "Hao phí lao động nói chung của người lao động"}], "answer": "B", "explanation": "B."}, {"id": "src-811c9106b75b-q017", "chapter": 2, "text": "Đâu là thước đo lượng giá trị hàng hóa ?", "options": [{"label": "A", "text": "Thời gian lao động cá biệt"}, {"label": "B", "text": "Năng suất lao động"}, {"label": "C", "text": "Thời gian lao động xã hội cần thiết"}, {"label": "D", "text": "Giá trị xã hội của hàng hóa"}], "answer": "C", "explanation": "C."}, {"id": "src-811c9106b75b-q018", "chapter": 2, "text": "Thuộc tính giá trị của hàng hóa có đặc điểm gì ?", "options": [{"label": "A", "text": "Giá trị hàng hóa là phạm trù vĩnh viễn"}, {"label": "B", "text": "Giá trị hàng hóa là phạm trù lịch sử"}, {"label": "C", "text": "Giá trị hàng hóa do giá trị trao đổi qui định"}, {"label": "D", "text": "Cả ý b và ý c đều đúng"}], "answer": "B", "explanation": "B."}, {"id": "src-811c9106b75b-q019", "chapter": 2, "text": "Ai là chủ thể chính tham gia thị trường ?", "options": [{"label": "A", "text": "Nhà hoạch định chính sách"}, {"label": "B", "text": "Công an kinh tế"}, {"label": "C", "text": "Ngân hàng và các trung gian tài chính"}, {"label": "D", "text": "Nhà sản xuất"}], "answer": "D", "explanation": "D là chủ thể sản xuất trực tiếp."}, {"id": "src-811c9106b75b-q020", "chapter": 2, "text": "Hàng hóa có mấy thuộc tính ?", "options": [{"label": "A", "text": "2"}, {"label": "B", "text": "3"}, {"label": "C", "text": "4"}, {"label": "D", "text": "Không xác định"}], "answer": "A", "explanation": "A: hai thuộc tính."}, {"id": "src-811c9106b75b-q021", "chapter": 2, "text": "Đâu là chức năng của tiền ?", "options": [{"label": "A", "text": "Đánh giá mức độ giàu có"}, {"label": "B", "text": "Thước đo mức độ tăng trưởng kinh tế của quốc gia"}, {"label": "C", "text": "Thước đo giá trị"}, {"label": "D", "text": "Tất cả các đáp án trên"}], "answer": "C", "explanation": "C."}, {"id": "src-811c9106b75b-q022", "chapter": 2, "text": "Giả có 3 cơ sở cùng sản xuất và cung ứng một loại hàng hóa X cho thị trường với thời gian lao động cá biệt (h/HH) và sản lượng hàng hóa X(HH) cung ứng như sau: Cơ sở A: 2h/HH  và cung ứng 250HH; Cơ sở B: 4h/HH và cung ứng 450HH; Cơ sở C: 1h/HH và cung ứng 100HH. TGLĐXHCT để sản xuất ra hàng hóa X là bao nhiêu ?", "options": [{"label": "A", "text": "2,75 h/HH"}, {"label": "B", "text": "3 h/HH"}, {"label": "C", "text": "3,25 h/HH"}, {"label": "D", "text": "3,75 h/HH"}], "answer": "B", "explanation": "(2×250 + 4×450 + 1×100)/(250+450+100) = 3 giờ/HH → B; theo mô hình bình quân gia quyền của bài tập."}, {"id": "src-811c9106b75b-q023", "chapter": 2, "text": "Vì sao C.Mác nghiên cứu giá trị sử dụng của hàng hóa trước?", "options": [{"label": "A", "text": "Giá trị sử dụng là cái dễ thấy nhất của hàng hóa"}, {"label": "B", "text": "Giá trị sử dụng là biểu hiện ra ngoài của giá trị"}, {"label": "C", "text": "Giá trị sử dụng là cơ sở của giá trị trao đổi"}, {"label": "D", "text": "Giá trị sử dụng là cái mà cả người sản xuất và người tiêu dùng đều quan tâm"}], "answer": "A", "explanation": "A: điểm xuất phát dễ quan sát. C dùng “cơ sở” không chính xác bằng “vật mang”."}, {"id": "src-811c9106b75b-q024", "chapter": 2, "text": "Lao động cụ thể và lao động trừu tượng là các khái niệm dùng để chỉ nội dung nào của lao động sản xuất hàng hóa?", "options": [{"label": "A", "text": "Trình độ hay mức độ phức tạp của lao động sản xuất hàng hóa"}, {"label": "B", "text": "Tính chất hai mặt của lao động sản xuất hàng hóa"}, {"label": "C", "text": "Giá trị xã hội của lao động sản xuất hàng hóa"}, {"label": "D", "text": "Tính chất tư nhân hóa của lao động sản xuất hàng hóa"}], "answer": "B", "explanation": "B."}, {"id": "src-811c9106b75b-q026", "chapter": 2, "text": "Đâu là môt trong những đặc trưng cơ bản của kinh tế thị trường ?", "options": [{"label": "A", "text": "Nhà nước và thị trường cùng nhau giải quyết các quan hệ, hiện tượng kinh tế nảy sinh"}, {"label": "B", "text": "Nhà nước giữ vai trò chủ đạo trong nền kinh tế"}, {"label": "C", "text": "Động lực trực tiếp của chủ thể sản xuất kinh doanh là lợi ích kinh tế - xã hội"}, {"label": "D", "text": "Tất cả các đáp án trên"}], "answer": "A", "explanation": "A. B khái quát sai vai trò nhà nước cho mọi nền kinh tế thị trường; C thêm “xã hội” vào động lực trực tiếp nên không chọn D."}, {"id": "src-811c9106b75b-q027", "chapter": 2, "text": "Khuyết tật của kinh tế thị trường là thể hiện ở nội dung nào ?", "options": [{"label": "A", "text": "Kinh tế thị trường là nền kinh tế mở, thị trường trong nước gắn liền với thị trường quốc tế"}, {"label": "B", "text": "Nền kinh tế thị trường luôn tiềm ẩn những rủi ro khủng hoảng"}, {"label": "C", "text": "Các chủ thể trong nền kinh tế thị trường luôn cạnh tranh với nhau"}, {"label": "D", "text": "Tất cả các đáp án trên"}], "answer": "B", "explanation": "B."}, {"id": "src-811c9106b75b-q028", "chapter": 2, "text": "Nguyên tắc ngang giá đòi hỏi các sản phẩm đem ra trao đổi trên thị trường phải đảm bảo điều kiện nào dưới đây ?", "options": [{"label": "A", "text": "Giá cả các hàng hóa bằng nhau"}, {"label": "B", "text": "Giá trị các hàng hóa bằng nhau"}, {"label": "C", "text": "Giá cả hàng hóa bằng giá trị hàng hóa"}, {"label": "D", "text": "Hao phí lao động cá biệt bằng hao phí lao động xã hội"}], "answer": "B", "explanation": "B: các lượng hàng đem đổi ngang giá."}, {"id": "src-811c9106b75b-q029", "chapter": 2, "text": "Quy luật giá trị có tác dụng gì ?", "options": [{"label": "A", "text": "Thúc đẩy cạnh tranh phát triển"}, {"label": "B", "text": "Thúc đẩy thị trường phát triển"}, {"label": "C", "text": "Kích thích cải tiến kỹ thuật, hợp lý hóa sản xuất"}, {"label": "D", "text": "Kích thích sản xuất và trao đổi hàng hóa"}], "answer": "C", "explanation": "C là tác dụng được nêu cụ thể; các phương án khác diễn đạt quá rộng."}, {"id": "src-811c9106b75b-q030", "chapter": 2, "text": "Tác dụng điều tiết sản xuất và lưu thông hàng hóa của qui luật giá trị thể hiện như thế nào ?", "options": [{"label": "A", "text": "Hàng hóa được vận chuyển từ nơi có giá cả thấp đến nơi có giá cả cao hơn"}, {"label": "B", "text": "Hình thành giá cả cân bằng trên thị trường"}, {"label": "C", "text": "Thúc đẩy năng lực thỏa mãn nhu cầu của xã hội"}, {"label": "D", "text": "Tất cả các đáp án trên"}], "answer": "A", "explanation": "A mô tả điều tiết lưu thông."}, {"id": "src-811c9106b75b-q032", "chapter": 2, "text": "Đâu là cơ chế tác động của quy luật giá trị ?", "options": [{"label": "A", "text": "Khối lượng hàng hóa được giao dịch trên trị trường"}, {"label": "B", "text": "Lượng người bán và người mua"}, {"label": "C", "text": "Sự biến động của giá cả hàng hóa"}, {"label": "D", "text": "Tất cả các đáp án trên"}], "answer": "C", "explanation": "C."}, {"id": "src-811c9106b75b-q033", "chapter": 2, "text": "Ưu thế của kinh tế thị trường thể hiện ở nội dung nào ?", "options": [{"label": "A", "text": "Minh bạch thông tin về sản phẩm"}, {"label": "B", "text": "Phân hóa xã hội"}, {"label": "C", "text": "Tạo ra các phương thức để thỏa mãn tối đa nhu cầu của con người"}, {"label": "D", "text": "Sự xuất hiện của độc quyền"}], "answer": "C", "explanation": "C."}, {"id": "src-811c9106b75b-q034", "chapter": 2, "text": "Các thuộc tính của hàng hóa có mối quan hệ với nhau như thế nào ?", "options": [{"label": "A", "text": "Thống nhất biện chứng với nhau"}, {"label": "B", "text": "Mâu thuẫn, bài trừ nhau"}, {"label": "C", "text": "Vừa thống nhất, vừa mâu thuẫn với nhau"}, {"label": "D", "text": "Độc lập, không có quan hệ với nhau"}], "answer": "C", "explanation": "C."}, {"id": "src-811c9106b75b-q035", "chapter": 2, "text": "Giá cả được hình thành một cách tự do là đặc trưng của cơ chế kinh tế nào ?", "options": [{"label": "A", "text": "Cơ chế kế hoạch hóa tập rung"}, {"label": "B", "text": "Cơ chế thị trường"}, {"label": "C", "text": "Cơ chế quản lý, điều tiết của nhà nước"}, {"label": "D", "text": "Tất cả các đáp án trên"}], "answer": "B", "explanation": "B."}, {"id": "src-811c9106b75b-q036", "chapter": 2, "text": "Vai trò cơ bản của người sản xuất trong nền kinh tế thị trường là gì ?", "options": [{"label": "A", "text": "Mua hàng hóa"}, {"label": "B", "text": "Quảng cáo sản phẩm"}, {"label": "C", "text": "Sản xuất và cung ứng hàng hóa"}, {"label": "D", "text": "Chỉ bán hàng hóa"}], "answer": "C", "explanation": "C."}, {"id": "src-811c9106b75b-q037", "chapter": 2, "text": "Vai trò của nhà nước trong nền kinh tế thị trường là gì ?", "options": [{"label": "A", "text": "Quản lý nhà nước về kinh tế"}, {"label": "B", "text": "Thu thuế"}, {"label": "C", "text": "Không có vai trò gì cụ thể"}, {"label": "D", "text": "Chỉ sản xuất các sản phẩm công ích"}], "answer": "A", "explanation": "A bao quát vai trò nhà nước."}, {"id": "src-811c9106b75b-q038", "chapter": 2, "text": "Tác động điều tiết sản xuất của qui luật giá trị thể hiện ở nội dung nào ?", "options": [{"label": "A", "text": "Vận chuyển hàng hóa từ nơi có giá cả thấp đến nơi có giá cả cao hơn"}, {"label": "B", "text": "Thay đổi qui mô sản xuất và sản lượng hàng hóa"}, {"label": "C", "text": "Thiết lập nên khái niệ hàng tồn kho"}, {"label": "D", "text": "Điều chỉnh giá cả hàng hóa"}], "answer": "B", "explanation": "B: thay đổi quy mô và sản lượng."}, {"id": "src-811c9106b75b-q039", "chapter": 2, "text": "Vì sao C.Mác bắt đầu nghiên cứu phương thức sản xuất TBCN từ hàng hóa?", "options": [{"label": "A", "text": "Hàng hóa là tế bào của kinh tế TBCN, chứa đựng những mầm mống mâu thuẫn của phương thức sản xuất TBCN"}, {"label": "B", "text": "Hàng hóa là hình thái biểu hiện phổ biến nhất của cải trong xã hội tư bản"}, {"label": "C", "text": "Hàng hóa là hình thái nguyên tố của của cải, phân tích hàng hóa là phân tích giá trị"}, {"label": "D", "text": "Tất cả các ý trên"}], "answer": "D", "explanation": "D tổng hợp ba góc nhìn."}, {"id": "src-811c9106b75b-q040", "chapter": 2, "text": "Thời gian lao động xã hội cần thiết không phụ thuộc vào nhân tố nào ?", "options": [{"label": "A", "text": "Năng suất lao động"}, {"label": "B", "text": "Cường độ lao động"}, {"label": "C", "text": "Qui mô sản xuất"}, {"label": "D", "text": "Trình độ lao động"}], "answer": "C", "explanation": "C không phải điều kiện trung bình dùng trong định nghĩa."}, {"id": "src-811c9106b75b-q042", "chapter": 2, "text": "Đặc điểm cơ bản của thời gian lao động xã hội cần thiết là gì ?", "options": [{"label": "A", "text": "Gần sát với thời gian lao động cá biệt của người cung cấp nhiều hàng hóa nhất cho thị trường"}, {"label": "B", "text": "Là trung bình cộng của các thời gian lao động cá biệt"}, {"label": "C", "text": "Được xác định dựa trên lượng hàng hóa trên thị trường"}, {"label": "D", "text": "Tất cả các đáp án trên"}], "answer": "A", "explanation": "A trong điều kiện sản xuất thông thường; không phải bình quân cộng giản đơn."}, {"id": "src-811c9106b75b-q043", "chapter": 2, "text": "Vai trò của quy luật lưu thông tiền tệ thể hiện ở nội dung nào?", "options": [{"label": "A", "text": "Kiểm soát lạm phát"}, {"label": "B", "text": "Điều chỉnh hành vi của người mua và người bán"}, {"label": "C", "text": "Điều chỉnh dung lượng hàng hóa trên thị trường"}, {"label": "D", "text": "Tất cả các đáp án trên"}], "answer": "A", "explanation": "A phù hợp nhất; B, C không mô tả vai trò trực tiếp."}, {"id": "src-811c9106b75b-q044", "chapter": 2, "text": "Mối quan hệ giữa giá cả hàng hóa và giá trị hàng hóa là gì?", "options": [{"label": "A", "text": "Giá cả quyết định giá trị"}, {"label": "B", "text": "Giá trị quyết định giá cả"}, {"label": "C", "text": "Độc lập với nhau"}, {"label": "D", "text": "Giá trị quyết định giá cả nhưng giá cả có tính độc lập tương đối"}], "answer": "D", "explanation": "D đầy đủ hơn B."}, {"id": "src-811c9106b75b-q045", "chapter": 2, "text": "Thực chất chức năng phương tiện thanh toán của tiền là gì?", "options": [{"label": "A", "text": "Tiền là trung gian cho trao đổi hàng hóa"}, {"label": "B", "text": "Tiền tham gia trực tiếp vào giao dịch mua, bán hàng hóa"}, {"label": "C", "text": "Tiền dùng để chi trả các giao dịch trước hoặc sau khi mua, bán"}, {"label": "D", "text": "Tất cả các đáp án trên"}], "answer": "C", "explanation": "C phân biệt với vai trò trung gian của tiền."}, {"id": "src-c1f911017e70-q001", "chapter": 1, "text": "Thuật ngữ Kinh tế chính trị xuất hiện lần đầu tiên vào năm nào?", "options": [{"label": "A", "text": "1818"}, {"label": "B", "text": "1883"}, {"label": "C", "text": "1615"}, {"label": "D", "text": "1895"}], "answer": "C", "explanation": "1615."}, {"id": "src-c1f911017e70-q002", "chapter": 1, "text": "Mục đích nghiên cứu của kinh tế chính trị là gì?", "options": [{"label": "A", "text": "Tìm ra các chính sách kinh tế"}, {"label": "B", "text": "Tìm ra các quy luật kinh tế cơ bản"}, {"label": "C", "text": "Tìm ra mối quan hệ giữa sản xuất và tiêu dùng"}, {"label": "D", "text": "Tìm ra mối quan hệ giữa hàng hóa và tiền tệ"}], "answer": "B", "explanation": "B nêu mục tiêu tìm quy luật."}, {"id": "src-c1f911017e70-q003", "chapter": 1, "text": "Kinh tế chính trị Mác – Lênin kế thừa trực tiếp những giá trị khoa học của trường phái kinh tế chính trị nào trong lịch sử?", "options": [{"label": "A", "text": "Chủ nghĩa trọng thương"}, {"label": "B", "text": "Kinh tế chính trị tiểu tư sản"}, {"label": "C", "text": "Kinh tế chính trị tư sản cổ điển Anh"}, {"label": "D", "text": "Kinh tế chính trị tầm thường"}], "answer": "C", "explanation": "C: nguồn kế thừa trực tiếp."}, {"id": "src-c1f911017e70-q004", "chapter": 1, "text": "Kinh tế chính trị Mác – Lênin ra đời vào thời điểm nào?", "options": [{"label": "A", "text": "Cuối thế kỉ 18"}, {"label": "B", "text": "Những năm 40 của thế kỉ 19"}, {"label": "C", "text": "Cuối thể kỉ 19"}, {"label": "D", "text": "Đầu thế kỉ 20"}], "answer": "B", "explanation": "B: thập niên 1840."}, {"id": "src-c1f911017e70-q005", "chapter": 1, "text": "Chức năng cơ bản của Kinh tế chính trị Mác – Lênin là gì?", "options": [{"label": "A", "text": "Tiêu chuẩn hành vi của các chủ thể kinh tế"}, {"label": "B", "text": "Nghiên cứu vai trò của các chủ thể kinh tế"}, {"label": "C", "text": "Chức năng thực tiễn"}, {"label": "D", "text": "Tất cả các đáp án trên"}], "answer": "C", "explanation": "C là một chức năng; A, B không phải tên chức năng."}, {"id": "src-c1f911017e70-q006", "chapter": 1, "text": "Phương pháp nghiên cứu đặc thù của Kinh tế chính trị Mác – Lênin là phương pháp nào?", "options": [{"label": "A", "text": "Sơ đồ tư duy"}, {"label": "B", "text": "Thống kê toán"}, {"label": "C", "text": "Trừu tượng hóa khoa học"}, {"label": "D", "text": "Tất cả các đáp án trên"}], "answer": "C", "explanation": "C: phương pháp đặc thù."}, {"id": "src-c1f911017e70-q007", "chapter": 1, "text": "Ai là người sáng lập ra trường phái Kinh tế chính trị Mác – Lênin?", "options": [{"label": "A", "text": "Karl Marx"}, {"label": "B", "text": "Karl Marx và V.I. Lenin"}, {"label": "C", "text": "Karl Marx và Ph. Engels"}, {"label": "D", "text": "Tất cả các đáp án trên"}], "answer": "C", "explanation": "C: Mác và Ăngghen sáng lập; Lênin phát triển."}, {"id": "src-c1f911017e70-q008", "chapter": 1, "text": "Đối tượng nghiên cứu của Kinh tế chính trị Mác – Lênin là gì?", "options": [{"label": "A", "text": "Thị trường và vai trò của các chủ thể tham gia thị trường tại các giai đoạn lịch sử nhất định"}, {"label": "B", "text": "Các yếu tố cơ bản của quá trình sản xuất"}, {"label": "C", "text": "Mối quan hệ giữa quan hệ sản xuất và lực lượng sản xuất trong các phương thức sản xuất khác nhau"}, {"label": "D", "text": "Các quan hệ của sản xuất và trao đổi trong mối liên hệ biện chứng với lực lượng sản xuất và kiến trúc thượng tầng tương ứng"}], "answer": "D", "explanation": "D mô tả đầy đủ đối tượng."}, {"id": "src-c1f911017e70-q009", "chapter": 1, "text": "Ý nghĩa nghiên cứu của Kinh tế chính trị Mác – Lênin là gì?", "options": [{"label": "A", "text": "Hình thành thế giới quan và phương pháp luận khoa học cho các chủ thể"}, {"label": "B", "text": "Hình thành tư duy trừu tượng hóa khoa học cho các chủ thể"}, {"label": "C", "text": "Giúp chủ thể thể kinh tế hiểu bản chất các hiện tượng, quá trình kinh tế; nắm vững quy luật kinh tế"}, {"label": "D", "text": "Tất cả các đáp án trên"}], "answer": "D", "explanation": "D bao quát các ý nghĩa đã nêu."}, {"id": "src-c1f911017e70-q010", "chapter": 1, "text": "Phương pháp trừu tượng hóa khoa học là cách thức thực hiện nghiên cứu bằng cách nào?", "options": [{"label": "A", "text": "Sử dụng đồ thị và các thuật toán"}, {"label": "B", "text": "Mô hình hóa các kết quả nghiên cứu bằng sơ đồ tư duy"}, {"label": "C", "text": "Gạt bỏ những yếu tố ngẫu nhiên, những hiện tượng tạm thời để thấy được bản chất bên trong"}, {"label": "D", "text": "Kết hợp logic và lịch sử để tiếp cận bản chất, các xu hướng và quy luật kinh tế"}], "answer": "C", "explanation": "C mô tả đúng thao tác trừu tượng hóa."}, {"id": "src-ebbea014b34e-q001", "chapter": 3, "text": "Điều kiện để tiền biến thành tư bản là", "options": [{"label": "A", "text": "Phải tích lũy được một lượng tiền lớn, tiền không được đưa vào kinh doanh với mục đích thu được giá trị thặng dư."}, {"label": "B", "text": "Phải tích lũy được một lượng tiền lớn, tiền được đưa vào kinh doanh với mục đích thu được giá trị thặng dư."}, {"label": "C", "text": "Phải tích lũy được một lượng hàng hóa lớn, hàng hóa phải được đưa vào kinh doanh với mục đích thu được giá trị thặng dư."}, {"label": "D", "text": "Phải tích lũy được một lượng máy móc lớn, máy móc được đưa vào kinh doanh với mục đích thu được giá trị thặng dư."}], "answer": "B", "explanation": ""}, {"id": "src-ebbea014b34e-q003", "chapter": 3, "text": "Điều kiện để sức lao đông trở thành hàng hóa là:", "options": [{"label": "A", "text": "Người lao động không được tự do, người lao động không có tư liệu sản xuất"}, {"label": "B", "text": "Người lao động được tự do thân thể, người lao động có tư liệu sản xuất (người lao động không có việc làm?)"}, {"label": "C", "text": "Người lao động được tự do thân thể, người lao động không có tư liệu sản xuất"}, {"label": "D", "text": "Người lao động phải được tự do, người lao động tự nguyện đi làm."}], "answer": "C", "explanation": ""}, {"id": "src-ebbea014b34e-q004", "chapter": 3, "text": "Khẳng định nào sau đây Không đúng về hàng hóa sức lao động?", "options": [{"label": "A", "text": "Mua bán chịu"}, {"label": "B", "text": "Giá cả bằng giá trị mới do sức lao động tạo ra"}, {"label": "C", "text": "Giá trị sử dụng quyết định Giá trị"}, {"label": "D", "text": "Hàng hóa sức lao động chỉ bán quyền sử dụng, chứ không bán quyền sở hữu"}], "answer": "B", "explanation": ""}, {"id": "src-ebbea014b34e-q005", "chapter": 3, "text": "Giá trị sức lao động được đo gián tiếp bằng", "options": [{"label": "A", "text": "Giá trị những tư liệu sản xuất để nuôi sống người lao động"}, {"label": "B", "text": "Giá trị sử dụng những tư liệu tiêu dùng để nuôi sống người lao động"}, {"label": "C", "text": "Giá trị những tư liệu tiêu dùng để nuôi sống nhà tư bản"}, {"label": "D", "text": "Giá trị những tư liệu tiêu dùng để nuôi sống người lao động"}], "answer": "D", "explanation": ""}, {"id": "src-ebbea014b34e-q006", "chapter": 3, "text": "Giá trị sử dụng của hàng hóa sức lao động, khi tiêu dùng sẽ tạo ra:", "options": [{"label": "A", "text": "Giá trị mới nhỏ hơn giá trị bản thân nó"}, {"label": "B", "text": "Giá trị mới bằng giá trị bản thân nó"}, {"label": "C", "text": "Giá trị mới lớn hơn giá trị bản thân nó"}, {"label": "D", "text": "Giá trị sử dụng mới lớn hơn giá trị sử dụng bản thân nó"}], "answer": "C", "explanation": ""}, {"id": "src-ebbea014b34e-q007", "chapter": 3, "text": "Giá trị thặng dư là…", "options": [{"label": "A", "text": "Toàn bộ phần lao động của công nhân"}, {"label": "B", "text": "Lao động sáng tạo của công nhân"}, {"label": "C", "text": "Phần lao động được trả công của công nhân"}, {"label": "D", "text": "Phần lao động không công của công nhân"}], "answer": "D", "explanation": ""}, {"id": "src-ebbea014b34e-q008", "chapter": 3, "text": "Ngày lao động của công nhân gồm hai phần:", "options": [{"label": "A", "text": "Thời gian lao động giản đơn và thời gian phức tạp"}, {"label": "B", "text": "Thời gian lao động giản đơn và thời gian lao tất yếu (cần thiết)"}, {"label": "C", "text": "Thời gian lao động tất yếu và thời gian lao động thặng dư"}, {"label": "D", "text": "Thời gian lao động phức tạp và thời gian lao động thặng dư"}], "answer": "C", "explanation": ""}, {"id": "src-ebbea014b34e-q009", "chapter": 3, "text": "Tư bản bất biến (c) là…", "options": [{"label": "A", "text": "Giá trị tư liệu sản xuất, giá trị của nó được tăng lên sau quá trình sản xuất"}, {"label": "B", "text": "Giá trị tư liệu sản xuất, giá trị của nó giảm đi sau quá trình sản xuất"}, {"label": "C", "text": "Giá trị tư liệu sản xuất, giá trị của nó không thay đổi sau quá trình sản xuất"}, {"label": "D", "text": "Giá trị tư liệu sản xuất, giá trị sử dụng của nó được bảo tồn và chuyển  vào sản phẩm"}], "answer": "C", "explanation": ""}, {"id": "src-ebbea014b34e-q010", "chapter": 3, "text": "Tư bản khả biến (v) là…", "options": [{"label": "A", "text": "Giá trị tư liệu sản xuất, giá trị của nó được tăng lên sau quá trình sản xuất"}, {"label": "B", "text": "Giá trị sức lao động, giá trị của nó tăng lên sau quá trình sản xuất"}, {"label": "C", "text": "Giá trị sức lao động, giá trị của nó không thay đổi sau quá trình sản xuất"}, {"label": "D", "text": "Giá trị sức lao động, giá trị của nó giảm đi sau quá trình sản xuất"}], "answer": "B", "explanation": ""}, {"id": "src-ebbea014b34e-q011", "chapter": 3, "text": "Căn cứ để phân chia tư bản bất biến và tư bản khả biến là:", "options": [{"label": "A", "text": "Căn cứ vào hai loại lao động là lao động cụ thể và lao động trừu tượng"}, {"label": "B", "text": "Căn cứ vào hai loại lao động là lao động giản đơn và lao động phức tạp"}, {"label": "C", "text": "Căn cứ vào tính chất hai mặt của lao động sản xuất hàng hóa"}, {"label": "D", "text": "Căn cứ vào vai trò của các bộ phận này trong quá trình sản xuất ra giá trị sử dụng"}], "answer": "C", "explanation": ""}, {"id": "src-ebbea014b34e-q012", "chapter": 3, "text": "Chọn câu Đúng? Tỷ suất giá trị thặng dư:", "options": [{"label": "A", "text": "Tỷ lệ thuận với tư bản bất biến"}, {"label": "B", "text": "Tỷ lệ nghịch với tư bản bất biến"}, {"label": "C", "text": "Tỷ lệ thuận với tư bản khả biến"}, {"label": "D", "text": "Tỷ lệ nghịch với tư bản khả biến"}], "answer": "D", "explanation": ""}, {"id": "src-ebbea014b34e-q013", "chapter": 3, "text": "Chọn câu Đúng? Dưới chủ nghĩa tư bản, bản chất tiền công là…", "options": [{"label": "A", "text": "Sự trả công cho lao động"}, {"label": "B", "text": "Giá cả của hàng hóa sức lao động"}, {"label": "C", "text": "Giá trị của hàng hóa lao động"}, {"label": "D", "text": "Giá trị sử dụng của hàng hóa sức lao động"}], "answer": "B", "explanation": ""}, {"id": "src-ebbea014b34e-q014", "chapter": 3, "text": "Chọn câu trả lời Đúng?", "options": [{"label": "A", "text": "Tư bản bất biến tạo ra giá trị thặng dư"}, {"label": "B", "text": "Tư bản khả biến tạo ra giá trị thặng dư"}, {"label": "C", "text": "Tư bản cố định tạo ra giá trị thặng dư"}, {"label": "D", "text": "Tư bản lưu động tạo ra giá trị thặng dư"}], "answer": "B", "explanation": ""}, {"id": "src-ebbea014b34e-q015", "chapter": 3, "text": "Tỷ suất giá trị thặng phản ánh:", "options": [{"label": "A", "text": "Quy mô bóc lột của nhà tư bản đối vơi công nhân làm thuê"}, {"label": "B", "text": "Trình độ bóc lột của nhà tư bản đối với công nhân làm thuê"}, {"label": "C", "text": "Năng lực sản xuất của nhà tư bản"}, {"label": "D", "text": "Chỉ cho nhà tư bản biết nơi đầu tư có lợi"}], "answer": "B", "explanation": ""}, {"id": "src-ebbea014b34e-q016", "chapter": 3, "text": "Hiện nay thường áp dụng phổ biến phương pháp sản xuất giá trị thặng dư nào?", "options": [{"label": "A", "text": "Phương pháp sản xuất giá trị thặng dư tuyệt đối"}, {"label": "B", "text": "Phương pháp sản xuất giá trị thặng dư tương đối"}, {"label": "C", "text": "Phương pháp sản xuất giá trị thặng dư siêu ngạch"}, {"label": "D", "text": "Phương pháp sản xuất lợi nhuận"}], "answer": "B", "explanation": ""}, {"id": "src-ebbea014b34e-q017", "chapter": 3, "text": "Quá trình tích lũy tư bản làm…", "options": [{"label": "A", "text": "Cấu tạo hữu cơ của tư bản không đổi"}, {"label": "B", "text": "Giảm cấu tạo hữu cơ của tư bản"}, {"label": "C", "text": "Tăng cấu tạo hữu cơ của tư bản"}, {"label": "D", "text": "Tăng cấu tạo kỹ thuật của tư bản"}], "answer": "C", "explanation": ""}, {"id": "src-ebbea014b34e-q018", "chapter": 3, "text": "Thời gian chu chuyển của tư bản được xác định bằng:", "options": [{"label": "A", "text": "Thời gian sản xuất + thời gian dự trữ sản xuất"}, {"label": "B", "text": "Thời gian sản xuất + thời gian lưu thông"}, {"label": "C", "text": "Thời gian lưu thông + thời gian vận chuyển"}, {"label": "D", "text": "Thời gian lưu thông + thời gian dự trữ sản xuất"}], "answer": "B", "explanation": ""}, {"id": "src-ebbea014b34e-q019", "chapter": 3, "text": "Tư bản bất biến và tư bản khả biến thuộc phạm trù tư bản nào?", "options": [{"label": "A", "text": "Tư bản sản xuất"}, {"label": "B", "text": "Tư bản tiền tệ"}, {"label": "C", "text": "Tư bản hàng hóa"}, {"label": "D", "text": "Tư bản lưu thông"}], "answer": "A", "explanation": ""}, {"id": "src-ebbea014b34e-q020", "chapter": 3, "text": "Chọn ý Đúng về mua bán hàng hóa sức lao động", "options": [{"label": "A", "text": "Giá cả > giá trị do sức lao động tạo ra"}, {"label": "B", "text": "Mua, bán không có thời hạn"}, {"label": "C", "text": "Bán chịu"}, {"label": "D", "text": "Bán cả quyền sở hữu và quyền sử dụng"}], "answer": "C", "explanation": ""}, {"id": "src-ebbea014b34e-q021", "chapter": 3, "text": "Sản xuất giá trị thặng dư tuyệt đối và sản xuất giá trị thặng dư tương đối giống nhau cơ bản ở điểm nào?", "options": [{"label": "A", "text": "Đều làm tăng tỷ suất giá trị thặng dư"}, {"label": "B", "text": "Đều làm giảm giá trị sức lao động"}, {"label": "C", "text": "Đều làm giảm thời gian lao động tất yếu"}, {"label": "D", "text": "Đều làm tăng độ dài ngày lao động"}], "answer": "A", "explanation": ""}, {"id": "src-ebbea014b34e-q022", "chapter": 3, "text": "Sản xuất giá trị thặng dư tương đối và giá trị thặng dư siêu ngạch không giống nhau ở điểm nào?", "options": [{"label": "A", "text": "Dựa trên tăng năng suất lao động"}, {"label": "B", "text": "Dựa trên rút ngắn thời gian lao động cần thiết"}, {"label": "C", "text": "Dựa trên tăng năng suất lao động xã hội"}, {"label": "D", "text": "Làm cho m’ tăng"}], "answer": "C", "explanation": ""}, {"id": "src-ebbea014b34e-q023", "chapter": 3, "text": "Chọn ý Đúng:", "options": [{"label": "A", "text": "Tư bản bất biến là một bộ phận của tư bản cố định"}, {"label": "B", "text": "Tư bản cố định là một bộ phận của tư bản bất biến"}, {"label": "C", "text": "Tư bản lưu động là một bộ phận của tư bản khả biến"}, {"label": "D", "text": "Tư bản khả biến là một bộ phận của tư bản bất biến"}], "answer": "B", "explanation": ""}, {"id": "src-ebbea014b34e-q024", "chapter": 3, "text": "Mục đích trực tiếp của nền sản xuất TBCN là:", "options": [{"label": "A", "text": "Sản xuất ra ngày càng nhiều của cải vật chất"}, {"label": "B", "text": "Mở rộng phạm vi thống trị của quan hệ sản xuất TBCN"}, {"label": "C", "text": "Tạo ra ngày càng nhiều giá trị thặng dư"}, {"label": "D", "text": "Làm cho lao động ngày càng lệ thuộc vào tư bản"}], "answer": "C", "explanation": ""}, {"id": "src-ebbea014b34e-q025", "chapter": 3, "text": "Chọn ý Đúng. Giá trị của tư liệu sản xuất đã tiêu dùng…", "options": [{"label": "A", "text": "Tham gia tạo thành giá trị mới của sản phẩm"}, {"label": "B", "text": "Tham gia tạo thành giá trị sức lao động"}, {"label": "C", "text": "Tham gia tạo thành giá trị của sản phẩm mới"}, {"label": "D", "text": "Không tham gia tạo thành giá trị sản phẩm mới"}], "answer": "C", "explanation": ""}, {"id": "src-ebbea014b34e-q026", "chapter": 3, "text": "Muốn tăng khối lượng giá trị thặng dư, nhà tư bản có thể sử dụng cách nào trong các cách dưới đây?", "options": [{"label": "A", "text": "Giảm thời gian lao động trong ngày, khi thời gian lao động cần thiết không đổi"}, {"label": "B", "text": "Giảm cường độ lao động khi ngày lao động không đổi"}, {"label": "C", "text": "Tăng giá trị sức lao động khi ngày lao động không đổi"}, {"label": "D", "text": "Giảm giá trị sức lao động khi ngày lao động không đổi"}], "answer": "D", "explanation": ""}, {"id": "src-ebbea014b34e-q027", "chapter": 3, "text": "Chọn ý đúng? Vai trò của máy móc trọng việc tạo ra giá trị thặng dư:", "options": [{"label": "A", "text": "Máy móc là nguồn gốc của giá trị thặng dư"}, {"label": "B", "text": "Máy móc là tiền đề vật chất cho việc tạo ra giá trị thặng dư"}, {"label": "C", "text": "Máy móc và sức lao động đều tạo ra giá trị thặng dư"}, {"label": "D", "text": "Máy móc là yếu tố quyết định để tạo ra giá trị thặng dư"}], "answer": "B", "explanation": ""}, {"id": "src-ebbea014b34e-q028", "chapter": 3, "text": "Ý kiến nào dưới đây là Không đúng", "options": [{"label": "A", "text": "Tích lũy tư bản là biến một phần giá trị thặng dư thành tư bản"}, {"label": "B", "text": "Nguồn gốc của tích lũy tư bản là giá trị thặng dư"}, {"label": "C", "text": "Động cơ của tích lũy tư bản cũng là giá trị thặng dư"}, {"label": "D", "text": "Tích lũy cơ bản là sự tiết kiệm tư bản"}], "answer": "D", "explanation": ""}, {"id": "src-ebbea014b34e-q029", "chapter": 3, "text": "Đâu là nguồn gốc của tích lũy tư bản:", "options": [{"label": "A", "text": "Tài sản thừa kế"}, {"label": "B", "text": "Của cải tiết kiệm của nhà tư bản"}, {"label": "C", "text": "Giá trị thặng dư"}, {"label": "D", "text": "Đi huy động từ các nhà tư bản khác"}], "answer": "C", "explanation": ""}, {"id": "src-ebbea014b34e-q030", "chapter": 3, "text": "Thời gian chu chuyển của tư bản gồm thời gian sản xuất và thời gian lưu thông. Thời gian sản xuất không gồm:", "options": [{"label": "A", "text": "Thời gian lao động"}, {"label": "B", "text": "Thời gian tiêu thụ hàng hóa"}, {"label": "C", "text": "Thời gian dự trữ sản xuất"}, {"label": "D", "text": "Thời gian gián đoạn lao động"}], "answer": "B", "explanation": ""}, {"id": "src-ebbea014b34e-q031", "chapter": 3, "text": "Cho tư bản đầu tư là 1000; cấu tạo hữu cơ của tư bản là 4/1, giá trị thặng dư m = 400. Xác định m'?", "options": [{"label": "A", "text": "100%"}, {"label": "B", "text": "150%"}, {"label": "C", "text": "200%"}, {"label": "D", "text": "250%"}], "answer": "C", "explanation": ""}, {"id": "src-ebbea014b34e-q033", "chapter": 3, "text": "Giá trị sử dụng của hàng hóa sức lao động được coi là", "options": [{"label": "A", "text": "Chìa khóa để giải quyết mâu thuẫn giữa tư bản và tư bản"}, {"label": "B", "text": "Chìa khóa để giải quyết mâu thuẫn công thức chung của tư bản"}, {"label": "C", "text": "Chìa khóa để giải quyết mâu thuẫn giữa tư bản và lao động"}, {"label": "D", "text": "Chìa khóa để giải quyết mâu thuẫn của lưu thông hàng hóa"}], "answer": "B", "explanation": ""}, {"id": "src-ebbea014b34e-q034", "chapter": 3, "text": "Khẳng định nào sau đây Đúng?", "options": [{"label": "A", "text": "Giá trị thặng dư cũng là giá trị"}, {"label": "B", "text": "Giá trị thặng dư và giá trị cùng bản chất"}, {"label": "C", "text": "Giá trị thặng dư là giá trị mới do người công nhân tạo ra"}, {"label": "D", "text": "Giá trị thặng dư là phần lao động không công do công nhân làm ra"}], "answer": "A", "explanation": ""}, {"id": "src-ebbea014b34e-q035", "chapter": 3, "text": "Khẳng định nào sau đây không đúng?", "options": [{"label": "A", "text": "Giá trị của tư liệu sản xuất tham gia tạo thành giá trị mới của sản phẩm"}, {"label": "B", "text": "Giá trị tư liệu sản xuất tham gia tạo thành giá trị của sản phẩm mới"}, {"label": "C", "text": "Giá trị của tư liệu sản xuất không tham gia tạo thành giá trị mới của sản phẩm"}, {"label": "D", "text": "Giá trị của tư liệu sản xuất được dịch chuyển sang giá trị của sản phẩm mới"}], "answer": "A", "explanation": ""}, {"id": "src-ebbea014b34e-q036", "chapter": 3, "text": "Chọn đáp án Không đúng", "options": [{"label": "A", "text": "Giá trị mới của sản phẩm = v + m"}, {"label": "B", "text": "Giá trị của sản phẩm mới = v + m"}, {"label": "C", "text": "Giá trị của tư liệu sản xuất = c"}, {"label": "D", "text": "Giá trị của sức lao động = v"}], "answer": "B", "explanation": ""}, {"id": "src-ebbea014b34e-q037", "chapter": 3, "text": "Chọn ý Không đúng:", "options": [{"label": "A", "text": "Giá trị thặng dư cũng là giá trị"}, {"label": "B", "text": "Giá trị thặng dư và giá trị giống nhau về chất, chỉ khác nhau về lượng trong một hàng hóa"}, {"label": "C", "text": "Giá trị thặng dư là lao động thặng dư kết tinh"}, {"label": "D", "text": "Giá trị thặng dư là tư liệu sản xuất kết tinh"}], "answer": "D", "explanation": ""}, {"id": "src-ebbea014b34e-q038", "chapter": 3, "text": "Trong phương pháp sản xuất giá trị thặng dư tuyệt đối, người lao động muốn giảm thời gian lao động trong ngày, còn nhà tư bản lại muốn kéo dài thời gian lao động trong ngày. Giới hạn tối thiểu của ngày lao động là bao nhiêu?", "options": [{"label": "A", "text": "Đủ bù đắp giá trị sức lao động của công nhân"}, {"label": "B", "text": "Do nhà tư bản quy định"}, {"label": "C", "text": "Lớn hơn thời gian lao động cần thiết"}, {"label": "D", "text": "Bằng thời gian lao động cần thiết"}], "answer": "C", "explanation": ""}, {"id": "src-ebbea014b34e-q039", "chapter": 3, "text": "Nếu nhà tư bản trả công theo đúng giá trị sức lao động thì có bóc lột giá trị thặng dư không?", "options": [{"label": "A", "text": "Không"}, {"label": "B", "text": "Có"}, {"label": "C", "text": "Bị lỗ vốn"}, {"label": "D", "text": "Hòa vốn"}], "answer": "B", "explanation": ""}, {"id": "src-ebbea014b34e-q040", "chapter": 3, "text": "Các yếu tố dưới đây, yếu tố nào không thuộc tư bản cố định:", "options": [{"label": "A", "text": "Nguyên vật liệu dùng cho sản xuất"}, {"label": "B", "text": "Các phương tiện vận tải"}, {"label": "C", "text": "Máy móc, thiết bị"}, {"label": "D", "text": "Đất đai làm mặt bằng sản xuất, nhà xưởng"}], "answer": "A", "explanation": ""}, {"id": "src-ebbea014b34e-q041", "chapter": 3, "text": "Các yếu tố dưới đây, yếu tố nào thuộc tư bản lưu động:", "options": [{"label": "A", "text": "Máy móc, nhà xưởng"}, {"label": "B", "text": "Đất đai làm mặt bằng sản xuất"}, {"label": "C", "text": "Tiền lương"}, {"label": "D", "text": "Các phương tiện vận tải"}], "answer": "C", "explanation": ""}, {"id": "src-ebbea014b34e-q042", "chapter": 3, "text": "Tổng giá cả sản xuất của 2 ngành A và B là 650. Tổng lợi nhuận của 2 ngành là 150. Xác định tỷ suất lợi nhuận bình quân?", "options": [{"label": "A", "text": "20%"}, {"label": "B", "text": "30%"}, {"label": "C", "text": "40%"}, {"label": "D", "text": "50%"}], "answer": "B", "explanation": ""}, {"id": "src-f38c2c0ea236-q001", "chapter": 2, "text": "Sản xuất tự cung, tự cấp có đặc trưng cơ bản nào sau đây?", "options": [{"label": "A", "text": "Sản phẩm làm ra để thoả mãn nhu cầu trực tiếp của người sản xuất;"}, {"label": "B", "text": "Sản phẩm làm ra để thoả mãn nhu cầu người khác;"}, {"label": "C", "text": "Sản phẩm làm ra để bán;"}, {"label": "D", "text": "Sản phẩm làm ra để trao đổi với sản phẩm của người khác."}], "answer": "A", "explanation": ""}, {"id": "src-f38c2c0ea236-q002", "chapter": 2, "text": "Sản xuất tự cung, tự cấp và sản xuất hàng hoá giống nhau ở điểm nào sau đây?", "options": [{"label": "A", "text": "Sản phẩm làm ra để thoả mãn nhu cầu trực tiếp của người sản xuất;"}, {"label": "B", "text": "Sản phẩm làm ra để thoả mãn nhu cầu xã hội;"}, {"label": "C", "text": "Quá trình sản xuất là sự kết hợp 2 yếu tố là sức lao động và tư liệu sản xuất để tạo ra sản phẩm;"}, {"label": "D", "text": "Quá trình tái sản xuất bao gồm 4 khâu là sản xuất, phân phối, trao đổi và tiêu dùng."}], "answer": "C", "explanation": ""}, {"id": "src-f38c2c0ea236-q003", "chapter": 2, "text": "Sản xuất hàng hoá ra đời khi và chỉ khi cùng đồng thời tồn tại mấy điều kiện?", "options": [{"label": "A", "text": "2"}, {"label": "B", "text": "3"}, {"label": "C", "text": "4"}, {"label": "D", "text": "5"}], "answer": "A", "explanation": ""}, {"id": "src-f38c2c0ea236-q004", "chapter": 2, "text": "Theo quan điểm C. Mác, hàng hoá gì ?", "options": [{"label": "A", "text": "Là sản phẩm của lao động;"}, {"label": "B", "text": "Là sản phẩm của lao động, có thể thoả mãn nhu cầu nào đó của con người;"}, {"label": "C", "text": "Là sản phẩm của lao động, có thể thoả mãn nhu cầu nào đó của con người và đi vào tiêu dùng;"}, {"label": "D", "text": "Là sản phẩm của lao động, có thể thoả mãn nhu cầu nào đó của con người thông qua trao đổi hay mua bán."}], "answer": "D", "explanation": ""}, {"id": "src-f38c2c0ea236-q005", "chapter": 2, "text": "Hàng hoá có mấy thuộc tính?", "options": [{"label": "A", "text": "2"}, {"label": "B", "text": "3"}, {"label": "C", "text": "4"}, {"label": "D", "text": "5"}], "answer": "A", "explanation": ""}, {"id": "src-f38c2c0ea236-q006", "chapter": 2, "text": "Giá trị sử dụng của hàng hoá là gì?", "options": [{"label": "A", "text": "Là biểu hiện bằng tiền của giá trị;"}, {"label": "B", "text": "Là hao phí lao động của người sản xuất hàng hoá kết tinh trong hàng hoá;"}, {"label": "C", "text": "Là công dụng của vật có thể thoả mãn nhu cầu nào đó của con người;"}, {"label": "D", "text": "Là quan hệ về một tỷ lệ nhất định, mà một hàng hoá này có thể đổi được một số lượng nhất định hàng hoá kia."}], "answer": "C", "explanation": ""}, {"id": "src-f38c2c0ea236-q007", "chapter": 2, "text": "Giá trị hàng hoá là gì?", "options": [{"label": "A", "text": "Là chi phí phí lao động của người sản xuất"}, {"label": "B", "text": "Là hao phí lao động của người sản xuất hàng hoá kết tinh trong hàng hoá;"}, {"label": "C", "text": "Là công dụng của vật có thể thoả mãn nhu cầu nào đó của con người;"}, {"label": "D", "text": "Là sản phẩm của lao động, có thể thoả mãn nhu cầu nào đó của con người;"}], "answer": "B", "explanation": ""}, {"id": "src-f38c2c0ea236-q008", "chapter": 2, "text": "Lao động cụ thể tạo ra thuộc tính nào của hàng hoá?", "options": [{"label": "A", "text": "Giá tri;"}, {"label": "B", "text": "Giá trị và giá trị sử dụng;"}, {"label": "C", "text": "Giá trị sử dụng;"}, {"label": "D", "text": "Giá trị trao đổi;"}], "answer": "C", "explanation": ""}, {"id": "src-f38c2c0ea236-q009", "chapter": 2, "text": "Lao động trừu tượng tạo ra thuộc tính nào của hàng hoá?", "options": [{"label": "A", "text": "Giá tri;"}, {"label": "B", "text": "Giá trị và giá trị sử dụng;"}, {"label": "C", "text": "Giá trị sử dụng;"}, {"label": "D", "text": "Giá trị trao đổi."}], "answer": "A", "explanation": ""}, {"id": "src-f38c2c0ea236-q010", "chapter": 2, "text": "Lượng giá trị hàng hoá được đo bằng thước đo nào sau đây?", "options": [{"label": "A", "text": "Thời gian lao động"}, {"label": "B", "text": "Thời gian lao động trong điều kiện xấu"}, {"label": "C", "text": "Thời gian lao động trong điều kiện tốt"}, {"label": "D", "text": "Thời gian lao động xã hội cần thiết."}], "answer": "D", "explanation": ""}, {"id": "src-f38c2c0ea236-q011", "chapter": 2, "text": "Có mấy cách tính lượng giá trị hàng hoá?", "options": [{"label": "A", "text": "2"}, {"label": "B", "text": "3"}, {"label": "C", "text": "4"}, {"label": "D", "text": "5"}], "answer": "A", "explanation": ""}, {"id": "src-f38c2c0ea236-q012", "chapter": 2, "text": "Theo C. Mác, có mấy nhân tố ảnh hưởng đến lượng giá trị hàng hoá?", "options": [{"label": "A", "text": "2"}, {"label": "B", "text": "3"}, {"label": "C", "text": "4"}, {"label": "D", "text": "5"}], "answer": "B", "explanation": ""}, {"id": "src-f38c2c0ea236-q013", "chapter": 2, "text": "Theo C. Mác, nhân tố nào sau đây ảnh hưởng đến lượng giá trị của hàng hoá?", "options": [{"label": "A", "text": "Thời gian lao động của người công nhân;"}, {"label": "B", "text": "Giá cả các yếu tố đầu vào của sản xuất;"}, {"label": "C", "text": "Lao động giản đơn và lao động phức tạp;"}, {"label": "D", "text": "Khoa học - công nghệ."}], "answer": "C", "explanation": ""}, {"id": "src-f38c2c0ea236-q014", "chapter": 2, "text": "Muốn tăng năng suất lao động, người ta thường áp dụng phương pháp nào sau đây?", "options": [{"label": "A", "text": "Tăng các yếu tố đầu vào của sản xuất;"}, {"label": "B", "text": "Đẩy mạnh ứng dụng các thành tựu khoa học – công nghệ;"}, {"label": "C", "text": "Tăng cường liên kết sản xuất;"}, {"label": "D", "text": "Tăng số lượng lao động."}], "answer": "B", "explanation": ""}, {"id": "src-f38c2c0ea236-q015", "chapter": 2, "text": "Tiền tệ ra đời trải qua mấy hình thái của giá trị?", "options": [{"label": "A", "text": "2"}, {"label": "B", "text": "3"}, {"label": "C", "text": "4"}, {"label": "D", "text": "5"}], "answer": "C", "explanation": ""}, {"id": "src-f38c2c0ea236-q016", "chapter": 2, "text": "Theo quan điểm của C. Mác, tiền tệ có mấy chức năng?", "options": [{"label": "A", "text": "2"}, {"label": "B", "text": "3"}, {"label": "C", "text": "4"}, {"label": "D", "text": "5"}], "answer": "D", "explanation": ""}, {"id": "src-f38c2c0ea236-q017", "chapter": 2, "text": "Tiền là loại hàng hoá nào sau đây?", "options": [{"label": "A", "text": "Hàng hoá thông thường;"}, {"label": "B", "text": "Hàng hoá phức tạp;"}, {"label": "C", "text": "Hàng hoá đặc biệt;"}, {"label": "D", "text": "Hàng hoá bình thường được nhân cách hoá."}], "answer": "C", "explanation": ""}, {"id": "src-f38c2c0ea236-q018", "chapter": 2, "text": "Hàng hoá nào sau đây là hàng hoá vô hình?", "options": [{"label": "A", "text": "Xe máy trong đại lý bán;"}, {"label": "B", "text": "Cắt tóc trong tiệm;"}, {"label": "C", "text": "Rau, quả bán trong chợ;"}, {"label": "D", "text": "Quần áo bán tại cửa hàng"}], "answer": "B", "explanation": ""}, {"id": "src-f38c2c0ea236-q019", "chapter": 2, "text": "Thị trường được phân làm mấy loại?", "options": [{"label": "A", "text": "2"}, {"label": "B", "text": "3"}, {"label": "C", "text": "4"}, {"label": "D", "text": "5"}], "answer": "C", "explanation": ""}, {"id": "src-f38c2c0ea236-q020", "chapter": 2, "text": "Nền kinh tế thị trường có mấy đặc trưng cơ bản?", "options": [{"label": "A", "text": "2"}, {"label": "B", "text": "3"}, {"label": "C", "text": "4"}, {"label": "D", "text": "5"}], "answer": "C", "explanation": ""}, {"id": "src-f38c2c0ea236-q021", "chapter": 2, "text": "Nội dung nào sau đây là ưu thế cơ bản của kinh tế thị trường?", "options": [{"label": "A", "text": "Tạo cơ hội cho con người phấn đấu vươn lên;"}, {"label": "B", "text": "Phát huy tốt nhất tiềm năng thế mạnh của mọi chủ thể kinh tế, các vùng, địa phương;"}, {"label": "C", "text": "Tạo điều kiện cho các chủ thể nâng cao năng lực cạnh tranh;"}, {"label": "D", "text": "Tạo điều kiện cho con người và xã hội phát triển toàn diện."}], "answer": "B", "explanation": ""}, {"id": "src-f38c2c0ea236-q022", "chapter": 2, "text": "Nội dung nào sau đây là khuyết tật cơ bản của kinh tế thị trường?", "options": [{"label": "A", "text": "Gây ra các căn bệnh khủng hoảng, thất nghiệp, lạm phát…"}, {"label": "B", "text": "Gây ra tình trạng người bóc lột người;"}, {"label": "C", "text": "Phân chia xã hội thành các giai cấp;"}, {"label": "D", "text": "Kìm hãm tiến bộ khoa học – công nghệ."}], "answer": "A", "explanation": ""}, {"id": "src-f38c2c0ea236-q023", "chapter": 2, "text": "Quy luật nào sau đây là quy luật kinh tế cơ bản của nền kinh tế thị trường?", "options": [{"label": "A", "text": "Quy luật giá cả độc quyền"}, {"label": "B", "text": "Quy luật cạnh tranh;"}, {"label": "C", "text": "Quy luật tích luỹ;"}, {"label": "D", "text": "Quy luật giá trị thặng dư"}], "answer": "B", "explanation": ""}, {"id": "src-f38c2c0ea236-q024", "chapter": 2, "text": "Quy luật giá trị là quy luật kinh tế cơ bản của nền sản xuất nào sau đây?", "options": [{"label": "A", "text": "Sản xuất tự cung, tự cấp;"}, {"label": "B", "text": "Sản xuất hàng hoá giản đơn;"}, {"label": "C", "text": "Sản xuất hàng hoá Tư bản chủ nghĩa;"}, {"label": "D", "text": "Của mọi nền sản xuất."}], "answer": "B", "explanation": ""}, {"id": "src-f38c2c0ea236-q025", "chapter": 2, "text": "Theo C. Mác, nội dung nào đưới đây phản ánh chính xác mối quan hệ giữa giá trị và giá trị sử dụng?", "options": [{"label": "A", "text": "Có quan hệ thống nhất trong hàng hoá;"}, {"label": "B", "text": "Có quan hệ mâu thuẫn trong hàng hoá;"}, {"label": "C", "text": "Có quan hệ thống nhất và không mâu thuẫn trong hàng hoá;"}, {"label": "D", "text": "Có quan hệ vừa thống nhất, vừa mâu thuẫn trong hàng hoá."}], "answer": "D", "explanation": ""}, {"id": "src-f38c2c0ea236-q026", "chapter": 2, "text": "Theo C. Mác, nội dung nào dưới đây phản ánh đúng mối quan hệ giữa giá trị và giá trị trao đổi?", "options": [{"label": "A", "text": "Giá trị là nội dung, giá trị trao đổi là hình thức biểu hiện của giá trị;"}, {"label": "B", "text": "Giá trị trao đổi là nội dung, còn giá trị là hình thức biểu hiện của giá trị trao đổi;"}, {"label": "C", "text": "Giá trị trao đổi quyết định giá trị;"}, {"label": "D", "text": "Giá trị trao đổi và giá trị có quan hệ tác động lẫn nhau."}], "answer": "A", "explanation": ""}, {"id": "src-f38c2c0ea236-q027", "chapter": 2, "text": "Theo C. Mác giá trị hàng hoá được quyết định bởi nhân tố nào sau đây?", "options": [{"label": "A", "text": "Công dụng của hàng hoá;"}, {"label": "B", "text": "Sự khan hiếm của hàng hoá;"}, {"label": "C", "text": "Hao phí sức lao động của người sản xuất hàng hoá;"}, {"label": "D", "text": "Giá cả thị trường."}], "answer": "C", "explanation": ""}, {"id": "src-f38c2c0ea236-q028", "chapter": 2, "text": "Theo C. Mác, giá cả hàng hoá được quyết định bởi nhân tố nào sau đây?", "options": [{"label": "A", "text": "Giá trị hàng hoá;"}, {"label": "B", "text": "Giá trị sử dụng của hàng hoá;"}, {"label": "C", "text": "Tương quan cung cầu về hàng hoá trên thị trường;"}, {"label": "D", "text": "Ý muốn của người bán."}], "answer": "A", "explanation": ""}, {"id": "src-f38c2c0ea236-q029", "chapter": 2, "text": "Lượng giá trị một đơn vị hàng hoá thay đổi theo quan hệ nào sau đây?", "options": [{"label": "A", "text": "Tỷ lệ nghich với tăng năng suất lao động;"}, {"label": "B", "text": "Tỷ lệ thuận với tăng năng suất lao động;"}, {"label": "C", "text": "Tỷ lệ nghịch với tăng cường độ lao động;"}, {"label": "D", "text": "Tỷ lệ thuận với tăng cường độ lao động."}], "answer": "A", "explanation": ""}, {"id": "src-f38c2c0ea236-q030", "chapter": 2, "text": "Khi tăng cường độ lao động, tổng sản phẩm sản xuất ra và giá trị một đơn vị hàng hoá thay đổi như thế nào?", "options": [{"label": "A", "text": "Tổng sản phẩm tăng, giá trị một đơn vị sản phẩm tăng;"}, {"label": "B", "text": "Tổng sản phẩm tăng, giá trị một đơn vị sản phẩm giảm;"}, {"label": "C", "text": "Tổng sản phẩm tăng, giá trị một đơn vị sản phẩm không đổi;"}, {"label": "D", "text": "Tổng sản phẩm không đổi, giá trị một đơn vị sản phẩm tăng."}], "answer": "C", "explanation": ""}, {"id": "src-f38c2c0ea236-q031", "chapter": 2, "text": "Vì sao hàng hoá có 2 thuộc tính?", "options": [{"label": "A", "text": "Lao động sản xuất hàng hoá có tính chất 2 mặt;"}, {"label": "B", "text": "Lao động sản xuất hàng hoá tạo ra sản phẩm để bán, để trao đổi;"}, {"label": "C", "text": "Lao động sản xuất hàng hoá là lao động có ích để tạo sản phẩm thoả mãn nhu cầu con người;"}, {"label": "D", "text": "Lao động của người sản xuất hàng hoá vừa mang tính chất tư nhân, vừa mang tính chất xã hội."}], "answer": "A", "explanation": ""}, {"id": "src-f38c2c0ea236-q032", "chapter": 2, "text": "Nội dung nào trong các nội dung sau đây tạo nên cuộc cách mạng trong Học thuyết giá trị của C. Mác?", "options": [{"label": "A", "text": "Hai thuộc tính của hàng hoá;"}, {"label": "B", "text": "Tính chất 2 mặt của lao động sản xuất hàng hoá;"}, {"label": "C", "text": "Lượng giá trị của hàng hoá;"}, {"label": "D", "text": "Quy luật giá trị."}], "answer": "B", "explanation": ""}, {"id": "src-f38c2c0ea236-q033", "chapter": 2, "text": "Thực hiện chức năng nào trong các chức năng sau đây, tiền vận động theo công thức H – T – H?", "options": [{"label": "A", "text": "Thước đo giá trị;"}, {"label": "B", "text": "Phương tiện lưu thông;"}, {"label": "C", "text": "Phương tiện thanh toán;"}, {"label": "D", "text": "Phương tiện cất trữ."}], "answer": "B", "explanation": ""}, {"id": "src-f38c2c0ea236-q034", "chapter": 2, "text": "Giữa lao động cụ thể và lao động trừu tượng có quan hệ như thế nào?", "options": [{"label": "A", "text": "Lao động trừu tượng là nội dung, lao động cụ thể là hình thức biểu hiện;"}, {"label": "B", "text": "Luôn thống nhất;"}, {"label": "C", "text": "Thống nhất và không có mâu thuẫn;"}, {"label": "D", "text": "Vừa thống nhất, vừa mâu thuẫn"}], "answer": "D", "explanation": ""}, {"id": "src-f38c2c0ea236-q035", "chapter": 2, "text": "Người ta nhận thức hoạt động của quy luật giá trị trên thị trường thông qua nhân tố nào sau đây?", "options": [{"label": "A", "text": "Giá trị trao đổi;"}, {"label": "B", "text": "Sự vận động của giá cả thị trường;"}, {"label": "C", "text": "Sự vận động của cung – cầu;"}, {"label": "D", "text": "Sự vận động của giá cả sản xuất."}], "answer": "B", "explanation": ""}, {"id": "src-f38c2c0ea236-q036", "chapter": 2, "text": "Phân hoá người sản xuất thành kẻ giàu, người nghèo tạo điều kiện cho sự ra đời của chủ nghĩa Tư Bản là tác dụng của quy luật nào trong các quy luật kinh tế sau đây?", "options": [{"label": "A", "text": "Quy luật cạnh tranh;"}, {"label": "B", "text": "Quy luật giá trị;"}, {"label": "C", "text": "Quy luật lưu thông tiền tệ;"}, {"label": "D", "text": "Quy luật cung – cầu;"}], "answer": "B", "explanation": ""}, {"id": "src-f38c2c0ea236-q037", "chapter": 2, "text": "Vì sao khi nghiên cứu sản xuất Tư bản chủ nghĩa, C. Mác bắt đầu từ nghiên cứu hàng hoá?", "options": [{"label": "A", "text": "Hàng hoá thoả mãn nhu cầu con người và đáp ứng sự phát triển xã hội;"}, {"label": "B", "text": "Hàng hoá là tế bào kinh tế của nền sản xuất TBCN;"}, {"label": "C", "text": "Hàng hoá là thước đo sự phát triển nền sản xuất TBCN;"}, {"label": "D", "text": "Hàng hoá là trung gian mà qua đó nhà tư bản bóc lột công nhân làm thuê để làm giàu."}], "answer": "B", "explanation": ""}, {"id": "src-f38c2c0ea236-q038", "chapter": 2, "text": "Trong nền kinh tế thị trường, các chủ thể sản xuất – kinh doanh hay gây ô nhiễm môi trường. Nguyên nhân nào trong các nguyên nhân sau dẫn tới tình trạng đó?", "options": [{"label": "A", "text": "Chủ doanh nghiệp không nắm chắc quy định của pháp luật;"}, {"label": "B", "text": "Ý thức chấp hành kỷ luật lao động của công nhân không tốt;"}, {"label": "C", "text": "Chủ doanh nghiệp chạy theo lợi nhuận;"}, {"label": "D", "text": "Cơ quan chức năng của nhà nước làm công tác thực thi pháp luật trong việc bảo vệ môi trường chưa tốt."}], "answer": "C", "explanation": ""}, {"id": "src-f38c2c0ea236-q039", "chapter": 2, "text": "Nền kinh tế lạm phát, biểu hiện ở chỉ số T > H; để cân bằng lượng tiền và hàng, nhà nước tiến hành điều tiết; biện pháp nào trong các biện pháp điều tiết sau mang lại sự cân bằng nhanh nhất?", "options": [{"label": "A", "text": "Giảm lượng tiền mặt trong lưu thông;"}, {"label": "B", "text": "Tăng sản xuất hàng hoá trong nước;"}, {"label": "C", "text": "Vừa tăng sản xuất hàng hoá trong nước vừa nhập khẩu hàng hoá để bù đắp thiếu hụt;"}, {"label": "D", "text": "Đồng thời giảm tiền mặt trong lưu thông và tăng cường sản xuất hàng hoá trong nước."}], "answer": "D", "explanation": ""}, {"id": "src-f38c2c0ea236-q040", "chapter": 2, "text": "Lý luận nào trong các lý luận sau đây là lý luận trung tâm trong lý luận giá trị của C. Mác?", "options": [{"label": "A", "text": "Hai thuộc tính của hàng hoá;"}, {"label": "B", "text": "Tính chất 2 mặt của lao động sản xuất hàng hoá;"}, {"label": "C", "text": "Lượng giá trị và các nhân tố ảnh hưởng đến lượng giá trị;"}, {"label": "D", "text": "Quy luật giá trị."}], "answer": "B", "explanation": ""}, {"id": "src-fa343e9bc4b6-q001", "chapter": 3, "text": "Căn cứ để phân chia tư bản cố định và tư bản lưu động là:", "options": [{"label": "A", "text": "Căn cứ vào tính chất chuyển giá trị sử dụng của nó vào trong sản phẩm mới."}, {"label": "B", "text": "Căn cứ vào tính chất chuyển giá trị của nó vào trong sản phẩm mới."}, {"label": "C", "text": "Căn cứ vào tính chất chuyển giá trị của nó vào trong  sản phẩm cũ."}, {"label": "D", "text": "Căn cứ vào tính vào tính chất chuyển giá trị thặng dư của nó vào trong sản phẩm mới."}], "answer": "B", "explanation": ""}, {"id": "src-fa343e9bc4b6-q002", "chapter": 3, "text": "Tính chất chuyển giá trị của tư bản cố định là:", "options": [{"label": "A", "text": "Chuyển giá trị ngay một lần vào trong sản phẩm mới."}, {"label": "B", "text": "Chuyển giá trị dần dần, từng phần một vào trong sản phẩm mới."}, {"label": "C", "text": "Chuyển giá trị sử dụng dần dần, từng phần một vào trong sản phẩm mới."}, {"label": "D", "text": "Chuyển giá trị dần dần, từng phần một vào trong sản phẩm cũ."}], "answer": "B", "explanation": ""}, {"id": "src-fa343e9bc4b6-q003", "chapter": 3, "text": "Tính chất chuyển giả trị của tư bản lưu động là", "options": [{"label": "A", "text": "Chuyển giá trị dẫn từng phần vào trong sản phẩm mới sau quá trình sản xuất."}, {"label": "B", "text": "Chuyển giá trị sử dụng toàn bộ vào trong sản phẩm mới sau quá trình sản xuất."}, {"label": "C", "text": "Chuyến giá trị toàn bộ vào trong sản phẩm mới sau quá trình sản xuất"}, {"label": "D", "text": "Chuyển giá trị toàn bộ vào trong sản phẩm cũ sau quá trình sản xuất."}], "answer": "C", "explanation": ""}, {"id": "src-fa343e9bc4b6-q004", "chapter": 3, "text": "Tư bản lưu động là bộ phận tư bản khi tham gia vào quá trình sản xuất:", "options": [{"label": "A", "text": "Giá trị của nó được chuyển dần vào sản phẩm mới bao gồm: nguyên nhân vật liệu và tiền công lao động"}, {"label": "B", "text": "Giá trị sử dụng của nó được chuyển ngay một lần vào sản phẩm mới, bao gồm: nguyên nhiên vật liệu và tiền công"}, {"label": "C", "text": "Giá trị của nó được chuyển ngay một lần vào sản phẩm cũ, bao gồm: nguyên nhiên vật liệu và tiền công lao động."}, {"label": "D", "text": "Giá trị của nó được chuyển ngay một lần vào sản phẩm mới, bao gồm: nguyên nhiên vật liệu và tiền công lao động"}], "answer": "D", "explanation": ""}, {"id": "src-fa343e9bc4b6-q005", "chapter": 3, "text": "Chu kỳ khủng hoảng kinh tế trong chủ nghĩa tư bản bao gồm:", "options": [{"label": "A", "text": "Khủng hoảng - suy giảm - phục hồi - hưng thịnh."}, {"label": "B", "text": "Khủng hoảng - tiêu điều - phục hồi - hưng thịnh."}, {"label": "C", "text": "Khủng hoảng - tiêu điều - suy giảm - hưng thịnh."}, {"label": "D", "text": "Suy giảm - tiêu điều - phục hồi - hưng thịnh."}], "answer": "B", "explanation": ""}, {"id": "src-fa343e9bc4b6-q006", "chapter": 3, "text": "Chi phí sản xuất tư bản chủ nghĩa (k):", "options": [{"label": "A", "text": "Bao gồm m và v (k = m+v)"}, {"label": "B", "text": "Bao gồm c và m (k=c+m)"}, {"label": "C", "text": "Bao gồm c và v (k =c+v)"}, {"label": "D", "text": "Bao gồm c, v và m(k=c+v+m)"}], "answer": "C", "explanation": ""}, {"id": "src-fa343e9bc4b6-q007", "chapter": 3, "text": "Về lượng, chi phí sản xuất tư bản chủ nghĩa (k)", "options": [{"label": "A", "text": "Bằng giá trị hàng hóa."}, {"label": "B", "text": "Lớn hơn giá trị hàng hóa."}, {"label": "C", "text": "Nhỏ hơn giá trị hàng hóa."}, {"label": "D", "text": "Nhỏ hơn giá trị thặng dư."}], "answer": "C", "explanation": ""}, {"id": "src-fa343e9bc4b6-q008", "chapter": 3, "text": "Về bản chất lợi nhuận và giá trị thặng dư đều là", "options": [{"label": "A", "text": "Lao động cụ thể của công nhân."}, {"label": "B", "text": "Lao động không công của công nhân"}, {"label": "C", "text": "Lao động trừu tượng của công nhân."}, {"label": "D", "text": "Lao động phức tạp của công nhân."}], "answer": "B", "explanation": ""}, {"id": "src-fa343e9bc4b6-q009", "chapter": 3, "text": "Khi hàng hóa được bán đúng giá trị thì:", "options": [{"label": "A", "text": "Lợi nhuận lớn hơn giá trị thặng dư."}, {"label": "B", "text": "Lợi nhuận bằng giá trị thăng dư"}, {"label": "C", "text": "Lợi nhuận nhỏ hơn giá trị thặng dư."}, {"label": "D", "text": "Giá trị thặng dư nhỏ hơn lợi nhuận thương nghiệp."}], "answer": "B", "explanation": ""}, {"id": "src-fa343e9bc4b6-q010", "chapter": 3, "text": "Về lượng lợi nhuận (p), có thể:", "options": [{"label": "A", "text": "Bằng, hoặc thấp hơn lượng giá trị thặng dư."}, {"label": "B", "text": "Cao hơn hoặc thấp hơn lượng giá trị thặng dư."}, {"label": "C", "text": "Bằng, cao hơn hoặc thấp hơn lượng giá trị thặng dư."}, {"label": "D", "text": "Bằng, hoặc cao hơn lương giá trị thặng dư."}], "answer": "C", "explanation": ""}, {"id": "src-fa343e9bc4b6-q011", "chapter": 3, "text": "Về lương tỷ suất lợi nhuận (p\")", "options": [{"label": "A", "text": "Luôn luôn nhỏ hơn giá trị thặng dư"}, {"label": "B", "text": "Luôn luôn lớn hơn tỷ suất giá trị thặng dư"}, {"label": "C", "text": "Luôn luôn bằng tỷ suất giá trị thặng dư."}, {"label": "D", "text": "Luôn luôn nhỏ hơn tỷ suất giá trị thặng dư"}], "answer": "D", "explanation": ""}, {"id": "src-fa343e9bc4b6-q012", "chapter": 3, "text": "Tỷ suất lợi nhuận (p”) là:", "options": [{"label": "A", "text": "Tỷ lệ phần trăm giữa tổng giá trị thặng dư và toàn bộ tư bản khả biến."}, {"label": "B", "text": "Tỷ lệ phần trăm giữa tổng giá trị thặng dư và toàn bộ tư bản ứng trước."}, {"label": "C", "text": "Tỷ lệ phần trăm giữa tổng giá trị thặng dư và toàn bộ tư bản bất biến."}, {"label": "D", "text": "Tỷ lệ phần trăm giữa tổng giá trị và toàn bộ tư bản ứng trước."}], "answer": "B", "explanation": ""}, {"id": "src-fa343e9bc4b6-q013", "chapter": 3, "text": "Cạnh tranh trong nội bộ ngành sẽ:", "options": [{"label": "A", "text": "Hình thành lợi nhuận bình quân."}, {"label": "B", "text": "Hình thành giá trị thị trường của hàng hóa."}, {"label": "C", "text": "Hình thành giá cả thị trường của hàng hóa."}, {"label": "D", "text": "Hình thành giá cả sản xuất."}], "answer": "B", "explanation": ""}, {"id": "src-fa343e9bc4b6-q014", "chapter": 3, "text": "Cạnh tranh trong nội bộ ngành là:", "options": [{"label": "A", "text": "Sự cạnh tranh giữa các nhà sản xuất trong cùng một ngành, sản xuất ra cùng một loại hàng hóa."}, {"label": "B", "text": "Sự cạnh tranh giữa các nhà sản xuất trong cùng một ngành, sản xuất ra cùng các loại hàng hóa."}, {"label": "C", "text": "Sự cạnh tranh giữa các nhà sản xuất trong các ngành, sản xuất ra cùng một loại hàng hóa."}, {"label": "D", "text": "Sự cạnh tranh giữa các nhà sản"}], "answer": "A", "explanation": ""}, {"id": "src-fa343e9bc4b6-q015", "chapter": 3, "text": "Mục đích của cạnh tranh trong nội bộ ngành là:", "options": [{"label": "A", "text": "Tìm kiếm lợi nhuận."}, {"label": "B", "text": "Tìm kiếm lợi nhuận siêu ngạch."}, {"label": "C", "text": "Tìm kiếm lợi nhuận bình quân."}, {"label": "D", "text": "Tìm kiếm giá trị siêu ngạch."}], "answer": "B", "explanation": ""}, {"id": "src-fa343e9bc4b6-q016", "chapter": 3, "text": "Cạnh tranh giữa các ngành là:", "options": [{"label": "A", "text": "Sự cạnh tranh giữa các nhà sản xuất trong cùng ngành."}, {"label": "B", "text": "Sự cạnh tranh giữa các nhà sản xuất ở các ngành khác nhau."}, {"label": "C", "text": "Sự cạnh tranh giữa các nhà sản xuất ở các nước khác nhau."}, {"label": "D", "text": "Sự cạnh tranh giữa các nhà tư bản ở các nước khác nhau."}], "answer": "B", "explanation": ""}, {"id": "src-fa343e9bc4b6-q017", "chapter": 3, "text": "Mục đích của cạnh tranh giữa các ngành là:", "options": [{"label": "A", "text": "Nhằm tìm kiếm ngành đầu tư có giá trị cao."}, {"label": "B", "text": "Nhằm tìm kiếm ngành đầu tư có lợi nhuận cao."}, {"label": "C", "text": "Nhằm tìm kiếm ngành đầu tư có giá trị sử dụng cao."}, {"label": "D", "text": "Nhằm tìm kiếm ngành đầu tư có giá cả cao."}], "answer": "B", "explanation": ""}, {"id": "src-fa343e9bc4b6-q018", "chapter": 3, "text": "Kết quả cạnh tranh giữa các ngành:", "options": [{"label": "A", "text": "Hình thành giá cả sản xuất."}, {"label": "B", "text": "Hình thành giá trị thị trường."}, {"label": "C", "text": "Hình thành lợi nhuận bình quân."}, {"label": "D", "text": "Hình thành chi phí sản xuất."}], "answer": "C", "explanation": ""}, {"id": "src-fa343e9bc4b6-q019", "chapter": 3, "text": "Lợi nhuận bình quân là:", "options": [{"label": "A", "text": "Lợi nhuận không bằng nhau của những lượng vốn tư bản đầu tư bằng nhau khi đầu tư vào các ngành khác nhau."}, {"label": "B", "text": "Lợi nhuận bằng nhau của những lượng vốn tư bản đầu tư không bằng nhau khi đầu tư vào các ngành khác nhau"}, {"label": "C", "text": "Lợi nhuận bằng nhau của những lượng vốn tư bản đầu tư bằng nhau khi đầu tư vào các ngành khác nhau."}, {"label": "D", "text": "Lợi nhuận khác nhau của những lượng vốn tư bản đầu tư khác nhau khi đầu tư vào các ngành khác nhau."}], "answer": "C", "explanation": ""}, {"id": "src-fa343e9bc4b6-q020", "chapter": 3, "text": "Tỷ suất lợi nhuận bình quân là:", "options": [{"label": "A", "text": "Tỷ suất lợi nhuận trung bình trong cùng một ngành."}, {"label": "B", "text": "Tỷ suất lợi nhuận trung bình giữa các ngành."}, {"label": "C", "text": "Tỷ suất lợi nhuận cao giữa các ngành."}, {"label": "D", "text": "Tỷ suất lợi nhuận độc quyền giữa các ngành."}], "answer": "B", "explanation": ""}, {"id": "src-fa343e9bc4b6-q021", "chapter": 3, "text": "Khi hình thành lợi nhuận bình quân giá trị hàng hóa sẽ chuyển thành:", "options": [{"label": "A", "text": "Giá trị thị trường."}, {"label": "B", "text": "Chi phí sản xuất."}, {"label": "C", "text": "Giá cả sản xuất."}, {"label": "D", "text": "Giá cả thị trường."}], "answer": "C", "explanation": ""}, {"id": "src-fa343e9bc4b6-q022", "chapter": 3, "text": "Giá cả sản xuất tư bản chủ nghĩa bằng:", "options": [{"label": "A", "text": "Chi phí sản xuất cộng tỷ suất lợi nhuận bình quân."}, {"label": "B", "text": "Chi phí sản xuất cộng giá trị thặng dư"}, {"label": "C", "text": "Chi phí sản xuất cộng lợi nhuận."}, {"label": "D", "text": "Chi phí sản xuất cộng lợi nhuận bình quân"}], "answer": "D", "explanation": "D: giá cả sản xuất = k + lợi nhuận bình quân."}, {"id": "src-fa343e9bc4b6-q023", "chapter": 3, "text": "Quy luật giá cả sản xuất là:", "options": [{"label": "A", "text": "Biểu hiện của quy luật giá trị sử dụng trong giai đoạn tự do cạnh tranh của chủ nghĩa tư bản."}, {"label": "B", "text": "Biểu hiện của quy luật giá trị trong giai đoạn tự do cạnh tranh của chủ nghĩa tư bản."}, {"label": "C", "text": "Biểu hiện của quy luật giá trị trong giai đoạn độc quyền của chủ nghĩa tư bản."}, {"label": "D", "text": "Biểu hiện của quy luật cạnh tranh trong giai đoạn độc quyền của chủ nghĩa tư bản."}], "answer": "B", "explanation": ""}, {"id": "src-fa343e9bc4b6-q024", "chapter": 3, "text": "Tư bản thương nghiệp trong chủ nghĩa tư bản là:", "options": [{"label": "A", "text": "Một bộ phận của tư bản nông nghiệp tách ra phục vụ quá trình lưu thông hàng hóa."}, {"label": "B", "text": "Một bộ phận của tư bản công nghiệp tách ra phục vụ quá trình lưu thông hàng hóa."}, {"label": "C", "text": "Một bộ phận của tư bản cho vay tách ra phục vụ quá trình lưu thông hàng hóa."}, {"label": "D", "text": "Một bộ phận của tư bản thương nghiệp tách ra phục vụ quá trình lưu thông hàng hóa."}], "answer": "B", "explanation": ""}, {"id": "src-fa343e9bc4b6-q025", "chapter": 3, "text": "Nguồn gốc lợi nhuận của tư bản thương nghiệp là:", "options": [{"label": "A", "text": "Một phần lợi nhuận tạo ra trong sản xuất mà nhà tư bản công nghiệp phải chuyển nhượng cho tư bản thương nghiệp."}, {"label": "B", "text": "Một phần giá trị thặng dư mà tư bản công nghiệp phải chuyển nhượng cho tư bản thương nghiệp."}, {"label": "C", "text": "Một phần tỷ suất lợi nhuận tạo ra trong sản xuất mà nhà tư bản công nghiệp phải chuyển nhượng cho tư bản thương nghiệp."}, {"label": "D", "text": "Một phần giá trị tạo ra trong nông nghiệp phải chuyển nhượng cho tư bản thương nghiệp."}], "answer": "B", "explanation": ""}, {"id": "src-fa343e9bc4b6-q026", "chapter": 3, "text": "Tư bản cho vay là:", "options": [{"label": "A", "text": "Tư bản hàng hóa mà người chủ của nó nhường cho người khác sử dụng trong một thời gian nhất định để thu lợi tức."}, {"label": "B", "text": "Tư bản tiền tệ mà người chủ của nó nhường cho người khác sử dụng trong một thời gian nhất định để thu lợi tức."}, {"label": "C", "text": "Từ bản tiền tệ mà người chủ của nó nhường cho người khác sử dụng trong một thời gian nhất định để thu lợi nhuận"}, {"label": "D", "text": "Tư bản sản xuất mà người chủ của nó nhường cho người khác sử dụng trong một thời gian nhất định để thu lợi tức."}], "answer": "B", "explanation": ""}, {"id": "src-fa343e9bc4b6-q027", "chapter": 3, "text": "Nguồn gốc của lợi tức là:", "options": [{"label": "A", "text": "Một phần sản phẩm thặng dư do công nhân tạo ra trong sản xuất."}, {"label": "B", "text": "Một phần lợi nhuận do công nhân tạo ra trong sản xuất."}, {"label": "C", "text": "Một phần giá trị thặng dư do công nhân tạo ra trong sản xuất."}, {"label": "D", "text": "Một phân ngoài chi phí do công nhân tạo ra trong"}], "answer": "C", "explanation": ""}, {"id": "src-fa343e9bc4b6-q028", "chapter": 3, "text": "Một trong những đặc điểm cơ bản của tư bản cho vay là:", "options": [{"label": "A", "text": "Quyền sở hữu gắn liền quyền sử dụng hiệu lệnh cấm"}, {"label": "B", "text": "Quyền sở hữu tách rời quyền quản lý."}, {"label": "C", "text": "Quyền sở hữu tách rời quyền sử dụng"}, {"label": "D", "text": "Quyền quản lý tách rời quyền sử dụng."}], "answer": "C", "explanation": ""}, {"id": "src-fa343e9bc4b6-q029", "chapter": 3, "text": "Công thức vận động của tư bản cho vay là:", "options": [{"label": "A", "text": "H- T’"}, {"label": "B", "text": "T- T’"}, {"label": "C", "text": "T- T"}, {"label": "D", "text": "H- H’"}], "answer": "B", "explanation": ""}, {"id": "src-fa343e9bc4b6-q030", "chapter": 3, "text": "Giới hạn của tỷ suất lợi tức (z”) là:", "options": [{"label": "A", "text": "o > z' > p'"}, {"label": "B", "text": "o <z' >p'"}, {"label": "C", "text": "o <z' <p'"}, {"label": "D", "text": "o>z' <p'"}], "answer": "C", "explanation": ""}, {"id": "src-fa343e9bc4b6-q031", "chapter": 3, "text": "Tỷ suất lợi tức (z”) là:", "options": [{"label": "A", "text": "Tỷ lệ phần trăm giữa giá trị thặng dư và tổng số tư  bản cho vay."}, {"label": "B", "text": "Tỷ lệ phần trăm giữa lợi tức và tổng số tư bản cho vay"}, {"label": "C", "text": "Tỷ lệ phần trăm giữa lợi nhuận và tổng số tư bản cho vay."}, {"label": "D", "text": "Tỷ lệ phần trăm giữa tỷ suất lợi nhuận và tổng số tư bản cho vay."}], "answer": "B", "explanation": ""}, {"id": "src-fa343e9bc4b6-q032", "chapter": 3, "text": "Địa tô tư bản là:", "options": [{"label": "A", "text": "Phần lợi nhuận ngoài lợi nhuận bình quân mà nhà tư bản kinh doanh nông nghiệp phải nộp cho chủ đất."}, {"label": "B", "text": "Phần tỷ suất giá trị thặng dư ngoài lợi nhuận bình quân mà nhà tư bản kinh doanh nông nghiệp phải nộp cho chủ đất."}, {"label": "C", "text": "Phần giá trị thặng dư ngoài lợi nhuận bình quân mà nhà tư bản kinh doanh nông nghiệp phải nộp cho chủ đất."}, {"label": "D", "text": "Phần giá trị thặng dư ngoài lợi nhuận mà nhà tư bản kinh doanh nông nghiệp phải nộp cho chủ đất."}], "answer": "C", "explanation": ""}, {"id": "src-fa343e9bc4b6-q033", "chapter": 3, "text": "Các hình thức cơ bản của địa tô tư bản chủ nghĩa:", "options": [{"label": "A", "text": "Địa tô chênh lệch I; địa tô chênh lệch II."}, {"label": "B", "text": "Địa tô tuyệt đối; địa tô độc quyền"}, {"label": "C", "text": "Địa tô chênh lệch, địa tô tuyệt đối"}, {"label": "D", "text": "Địa tô chênh lệch, địa tô độc quyền"}], "answer": "C", "explanation": ""}, {"id": "src-fa343e9bc4b6-q034", "chapter": 3, "text": "Địa tô tuyệt đối là địa tô mà", "options": [{"label": "A", "text": "Nhà tư bản đi thuê đất phải trả cho chủ đất, dù thuê mướn bất kỳ loại ruộng đất nào."}, {"label": "B", "text": "Nhà tư bản đi thuê đất phải trả cho chủ đất, khi thuê mướn ruộng đất tốt."}, {"label": "C", "text": "Nhà tư bản đi thuê đất không phải trả cho chủ đất, dù thuê mướn bất kỳ loại ruộng đất nào."}, {"label": "D", "text": "Nhà tư bản đi thuê đất phải trả cho chủ đất, khi thuê mướn ruộng đất xấu."}], "answer": "A", "explanation": ""}, {"id": "src-fa343e9bc4b6-q035", "chapter": 3, "text": "Điểm giống nhau giữa địa tô chênh lệch và địa tô tuyệt đối là:", "options": [{"label": "A", "text": "Có nguồn gốc từ giá trị thặng dư"}, {"label": "B", "text": "Tư bản bất biến."}, {"label": "C", "text": "Có nguồn gốc từ giá trị trao đổi."}, {"label": "D", "text": "Có nguồn gốc từ giá trị."}], "answer": "A", "explanation": ""}]};
